/** All translations for zizhitongjian ch.023 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起旃蒙協洽，盡柔兆敦牂，凡十二年。", literal: "From Zhanmeng Xiehe through Rouzhao Dunjiang; twelve years in all.", idiomatic: "From Zhanmeng Xiehe through Rouzhao Dunjiang—twelve years in all." },
  { zh: "1夏，益州夷二十四邑、三萬餘人皆反。", literal: "1. In summer, the Yi of Yizhou—twenty-four settlements and more than thirty thousand people—all rebelled.", idiomatic: "1. In summer the Yi of Yizhou—twenty-four settlements and more than thirty thousand people—all rebelled." },
  { zh: "遣水衡都尉呂辟胡募吏民及發犍為、蜀郡奔命往擊，大破之。", literal: "The Chief Steward for Water and Parks Lü Pihu was sent to recruit officials and commoners and to raise emergency levies from Qianwei and Shu commanderies to attack them; he inflicted a great defeat.", idiomatic: "Chief Steward for Water and Parks Lü Pihu was sent to recruit officials and commoners and raise emergency levies from Qianwei and Shu to attack them; he won a crushing victory." },
  { zh: "----2秋，七月，赦天下。", literal: "----2 In autumn, the seventh month, an amnesty was proclaimed for all under Heaven.", idiomatic: "----2 In autumn, the seventh month, an amnesty was proclaimed for all under Heaven." },
  { zh: "----3大雨，至於十月，渭橋絕。", literal: "----3 Heavy rain lasted until the tenth month; the Wei River bridge was cut off.", idiomatic: "----3 Heavy rain lasted until the tenth month; the Wei River bridge was washed out." },
  { zh: "----4武帝初崩，賜諸侯王璽書。", literal: "----4 When Emperor Wu first died, imperial-seal letters of appointment were bestowed on the feudal kings.", idiomatic: "----4 When Emperor Wu first died, imperial-seal letters of appointment were sent to the feudal kings." },
  { zh: "燕王旦得書不肯哭，曰：「璽書封小，京師疑有變。", literal: "The Prince of Yan, Dan, received the letter and refused to mourn, saying: \"The seal on the letter is small; the capital suspects there has been a change.", idiomatic: "Prince Dan of Yan received the letter and refused to mourn, saying, \"The seal on the letter is small—the capital may suspect something has changed." },
  { zh: "」遣幸臣壽西長、孫縱之、王孺等之長安，以問禮儀為名，陰刺候朝廷事。", literal: "\" He sent favored retainers Shou Xichang, Sun Zongzhi, Wang Ru, and others to Chang'an, under the pretext of inquiring about ritual, to spy secretly on affairs at court.", idiomatic: "\" He sent favored retainers Shou Xichang, Sun Zongzhi, Wang Ru, and others to Chang'an, ostensibly to inquire about ritual, but secretly to spy on affairs at court." },
  { zh: "及有詔褒賜旦錢三十萬，益封萬三千戶，旦怒曰：「我當為帝，何賜也！", literal: "When an edict came praising and rewarding Dan with three hundred thousand cash and an additional enfeoffment of thirteen thousand households, Dan angrily said: \"I ought to be emperor—what is this reward!", idiomatic: "When an edict came praising and rewarding Dan with three hundred thousand cash and an additional enfeoffment of thirteen thousand households, Dan raged, \"I ought to be emperor—what is this reward!" },
  { zh: "」遂與宗室中山哀王子長、齊孝王孫澤等結謀，詐言以武帝時受詔，得職吏事，修武備，備非常。", literal: "\" He thereupon joined in conspiracy with the imperial clansman Chang, son of King Ai of Zhongshan, Sun Ze, grandson of King Xiao of Qi, and others, falsely claiming that in Emperor Wu's time he had received an edict empowering him to manage officials and affairs, repair armaments, and guard against the unexpected.", idiomatic: "\" He thereupon conspired with the imperial clansman Chang, son of King Ai of Zhongshan, Sun Ze, grandson of King Xiao of Qi, and others, falsely claiming that in Emperor Wu's time he had received an edict empowering him to manage officials, repair armaments, and guard against the unexpected." },
  { zh: "郎中成軫謂旦曰：「大王失職，獨可起而索，不可坐而得也。", literal: "Palace Gentleman Cheng Zhen said to Dan: \"Your Highness has lost your post; you can only rise and demand it—you cannot sit and obtain it.", idiomatic: "Palace Gentleman Cheng Zhen told Dan, \"Your Highness has lost your place; you can only rise and demand it—you cannot sit and obtain it." },
  { zh: "大王壹起，國中雖女子皆奮臂隨大王。", literal: "If Your Highness rises once, throughout the state even women will swing their arms and follow Your Highness.", idiomatic: "If Your Highness rises once, throughout the state even women will take up arms and follow you." },
  { zh: "」旦即與澤謀，為奸書，言：「少帝非武帝子，大臣所共立；", literal: "\" Dan at once plotted with Ze and forged a wicked letter, saying: \"The young emperor is not Emperor Wu's son; the great ministers jointly established him;", idiomatic: "\" Dan at once plotted with Ze and forged a seditious letter, saying, \"The young emperor is not Emperor Wu's son; the great ministers jointly established him;" },
  { zh: "天下宜共伐之！", literal: "all under Heaven ought jointly to attack him!", idiomatic: "all under Heaven ought jointly to attack him!" },
  { zh: "」使人傳行郡國以搖動百姓。", literal: "\" He sent men to circulate it through the commanderies and kingdoms to stir up the people.", idiomatic: "\" He sent men to circulate it through the commanderies and kingdoms to stir up the people." },
  { zh: "澤謀歸發兵臨菑，殺青州刺史雋不疑。", literal: "Ze plotted to return, raise troops, advance on Zi, and kill Qingzhou Inspector Juan Buyi.", idiomatic: "Ze plotted to return, raise troops, advance on Zi, and kill Qingzhou Inspector Juan Buyi." },
  { zh: "旦招來郡國奸人，賦斂銅鐵作甲兵，數閱其車騎、材官卒，發民大獵以講士馬，須期日。", literal: "Dan gathered wicked men from the commanderies and kingdoms, levied copper and iron to make armor and weapons, repeatedly reviewed his chariots, cavalry, and skilled soldiers, and mobilized the people for great hunts to drill troops and horses, awaiting the appointed day.", idiomatic: "Dan gathered wicked men from the commanderies and kingdoms, levied copper and iron for armor and weapons, repeatedly reviewed his chariots, cavalry, and skilled troops, and mobilized the people for great hunts to drill men and horses, awaiting the appointed day." },
  { zh: "郎中韓義等數諫旦，旦殺義等凡十五人。", literal: "Palace Gentlemen Han Yi and others repeatedly admonished Dan; Dan killed Yi and the rest, fifteen in all.", idiomatic: "Palace Gentlemen Han Yi and others repeatedly admonished Dan; Dan killed Yi and fourteen others—fifteen in all." },
  { zh: "會缾侯成知澤等謀，以告雋不疑。", literal: "It happened that Marquis of Ping Cheng learned of Ze's plot and reported it to Juan Buyi.", idiomatic: "Marquis of Ping Cheng learned of Ze's plot and reported it to Juan Buyi." },
  { zh: "八月，不疑收捕澤等以聞。", literal: "In the eighth month, Buyi arrested Ze and the others and reported it.", idiomatic: "In the eighth month Buyi arrested Ze and the others and reported it." },
  { zh: "天子遣大鴻臚丞治，連引燕王。", literal: "The Son of Heaven sent the Grand Herald's assistant to investigate, implicating the Prince of Yan in succession.", idiomatic: "The emperor sent the Grand Herald's assistant to investigate, implicating the Prince of Yan in succession." },
  { zh: "有詔，以燕王至親，勿治；", literal: "An edict stated that because the Prince of Yan was a close kinsman, he was not to be prosecuted;", idiomatic: "An edict stated that because the Prince of Yan was a close kinsman, he was not to be prosecuted;" },
  { zh: "而澤等皆伏誅。", literal: "but Ze and the others were all executed.", idiomatic: "but Ze and the others were all executed." },
  { zh: "遷雋不疑為京兆尹。", literal: "Juan Buyi was transferred to be Metropolitan Commandant.", idiomatic: "Juan Buyi was transferred to Metropolitan Commandant." },
  { zh: "不疑為京兆尹，吏民敬其威信。", literal: "As Metropolitan Commandant, Buyi was respected by officials and commoners for his authority and trustworthiness.", idiomatic: "As Metropolitan Commandant, Buyi won respect from officials and commoners for his authority and trustworthiness." },
  { zh: "每行縣、錄囚徒還，其母輒問不疑：「有所平反？", literal: "Whenever he toured the counties and returned from recording prisoners, his mother would ask Buyi: \"Were any cases reversed?", idiomatic: "Whenever he toured the counties and returned from reviewing prisoners, his mother would ask Buyi, \"Were any cases reversed?" },
  { zh: "活幾何人？", literal: "How many people were spared?", idiomatic: "How many people were spared?" },
  { zh: "」即不疑多有所平反，母喜笑異於他時；", literal: "\" If Buyi had reversed many cases, his mother would laugh with joy unlike at other times;", idiomatic: "\" If Buyi had reversed many cases, his mother would laugh with joy unlike at other times;" },
  { zh: "或無所出，母怒，為不食。", literal: "if there were none, his mother grew angry and would not eat.", idiomatic: "if there were none, his mother grew angry and refused to eat." },
  { zh: "故不疑為吏，嚴而不殘。", literal: "For this reason Buyi as an official was stern but not cruel.", idiomatic: "For this reason Buyi as an official was stern but not cruel." },
  { zh: "----5九月，丙子，秺敬侯金日磾薨。", literal: "----5 In the ninth month, on bingzi, Marquis Jing of Di Jin Midi died.", idiomatic: "----5 In the ninth month, on bingzi, Marquis Jing of Di Jin Midi died." },
  { zh: "初，武帝病，有遺詔，封金日磾為秺侯，上官桀為安陽侯，霍光為博陸侯；", literal: "At the outset, when Emperor Wu was ill, there was a testamentary edict enfeoffing Jin Midi as Marquis of Di, Shangguan Jie as Marquis of Anyang, and Huo Guang as Marquis of Bolu;", idiomatic: "At the outset, when Emperor Wu was ill, a testamentary edict enfeoffed Jin Midi as Marquis of Di, Shangguan Jie as Marquis of Anyang, and Huo Guang as Marquis of Bolu;" },
  { zh: "皆以前捕反者馬何羅等功封。", literal: "all were enfeoffed for their former merit in capturing the rebel Ma Heluo and others.", idiomatic: "all were enfeoffed for their former merit in capturing the rebel Ma Heluo and others." },
  { zh: "日磾以帝少，不受封，光等亦不敢受。", literal: "Midi, because the emperor was young, did not accept the enfeoffment; Guang and the others also did not dare accept.", idiomatic: "Midi, because the emperor was young, did not accept the enfeoffment; Guang and the others also did not dare accept." },
  { zh: "及日磾病困，光白封，日磾臥受印綬；", literal: "When Midi's illness grew critical, Guang reported and enfeoffed him; Midi received the seal and ribbon while lying down;", idiomatic: "When Midi's illness grew critical, Guang reported and enfeoffed him; Midi received the seal and ribbon while lying down;" },
  { zh: "一日薨。", literal: "and died the next day.", idiomatic: "and died the next day." },
  { zh: "日磾兩子賞、建俱侍中，與帝略同年，共臥起。", literal: "Midi's two sons Shang and Jian were both Palace Attendants, roughly the emperor's age, sharing bed and rising together.", idiomatic: "Midi's two sons Shang and Jian were both Palace Attendants, roughly the emperor's age, sharing bed and rising with him." },
  { zh: "賞為奉車，建駙馬都尉。", literal: "Shang was Director of the Imperial Carriage; Jian was Commandant of the Palace Steeds.", idiomatic: "Shang was Director of the Imperial Carriage; Jian was Commandant of the Palace Steeds." },
  { zh: "及賞嗣侯，佩兩綬，上謂霍將軍曰：「金氏兄弟兩人，不可使俱兩綬邪？", literal: "When Shang succeeded to the marquisate and wore two ribbons, the emperor said to General Huo: \"The two Jin brothers—could they not both wear two ribbons?", idiomatic: "When Shang succeeded to the marquisate and wore two ribbons, the emperor said to General Huo, \"The two Jin brothers—could they not both wear two ribbons?" },
  { zh: "」對曰：「賞自嗣父為侯耳。", literal: "\" He replied: \"Shang has merely succeeded his father as marquis.", idiomatic: "\" He replied, \"Shang has merely succeeded his father as marquis." },
  { zh: "」上笑曰：「侯不在我與將軍乎？", literal: "\" The emperor laughed and said: \"Are marquisates not in my hands and the general's?", idiomatic: "\" The emperor laughed and said, \"Are marquisates not in my hands and yours?" },
  { zh: "」對曰：「先帝之約，有功乃得封侯。", literal: "\" He replied: \"The former emperor's covenant: only with merit may one be enfeoffed as marquis.", idiomatic: "\" He replied, \"The former emperor's covenant: only with merit may one be enfeoffed as marquis." },
  { zh: "」遂止。", literal: "\" The matter thereupon ceased.", idiomatic: "\" The matter thereupon ceased." },
  { zh: "----6閏月，遣故廷尉王平等五人持節行郡國，舉賢良，問民疾苦、冤、失職者。", literal: "----6 In the intercalary month, the former Minister of Justice Wang Ping and five others were sent with credentials to tour the commanderies and kingdoms, recommend the worthy and good, and inquire into the people's suffering, wrongs, and dereliction of duty.", idiomatic: "----6 In the intercalary month, former Minister of Justice Wang Ping and five others were sent with credentials to tour the commanderies and kingdoms, recommend the worthy and good, and inquire into popular suffering, wrongs, and dereliction of duty." },
  { zh: "----7冬，無冰。", literal: "----7 In winter, there was no ice.", idiomatic: "----7 In winter there was no ice." },
  { zh: "1春，正月，封大將軍光為博陸侯，左將軍桀為安陽侯。", literal: "1. In spring, the first month, Grand General Guang was enfeoffed as Marquis of Bolu and Left General Jie as Marquis of Anyang.", idiomatic: "1. In spring, the first month, Grand General Guang was enfeoffed as Marquis of Bolu and Left General Jie as Marquis of Anyang." },
  { zh: "----2或說霍光曰：「將軍不見諸呂之事乎？", literal: "----2 Someone said to Huo Guang: \"General, have you not seen what befell the Lü clan?", idiomatic: "----2 Someone said to Huo Guang, \"General, have you not seen what befell the Lü clan?" },
  { zh: "處伊尹、周公之位，攝政擅權，而背宗室，不與共職，是以天下不信，卒至於滅亡。", literal: "Occupying the positions of Yi Yin and the Duke of Zhou, holding regency and monopolizing power, yet turning your back on the imperial clan and not sharing office with them—for this reason all under Heaven did not trust them, and they ended in extinction.", idiomatic: "Occupying the positions of Yi Yin and the Duke of Zhou, holding regency and monopolizing power, yet turning your back on the imperial clan and not sharing office with them—for this reason the realm did not trust them, and they ended in extinction." },
  { zh: "今將軍當盛位，帝春秋富，宜納宗室，又多與大臣共事，反諸呂道。", literal: "Now the general occupies a flourishing position and the emperor's years are still rich; you ought to bring in the imperial clan and share many affairs with the great ministers—reversing the way of the Lü.", idiomatic: "Now you occupy a flourishing position and the emperor is still young; you ought to bring in the imperial clan and share many affairs with the great ministers—reversing the Lü path." },
  { zh: "如是，則可以免患。", literal: "If so, you may escape calamity.", idiomatic: "If so, you may escape calamity." },
  { zh: "」光然之，乃擇宗室可用者，遂拜楚元王孫辟疆及宗室劉長樂皆為光祿大夫，辟疆守長樂衛尉。", literal: "\" Guang assented; he thereupon selected usable members of the imperial clan and appointed the grandson of King Yuan of Chu, Pijiang, and the clansman Liu Changle both as Palace Grandees, with Pijiang holding office as Commandant of the Guards for Changle.", idiomatic: "\" Guang assented; he selected usable members of the imperial clan and appointed King Yuan of Chu's grandson Pijiang and clansman Liu Changle both Palace Grandees, with Pijiang serving as Commandant of the Guards for Changle." },
  { zh: "----3三月，遣使者振貸貧民無種、食者。", literal: "----3 In the third month, envoys were sent to relieve and lend to poor commoners without seed or food.", idiomatic: "----3 In the third month envoys were sent to relieve and lend to poor commoners without seed or food." },
  { zh: "----4秋，八月，詔曰：「往年災害多，今年蠶、麥傷，所振貸種、食勿收責，毋令民出今年田租。", literal: "----4 In autumn, the eighth month, an edict said: \"In former years disasters were many; this year silkworms and wheat were harmed. The seed and food that were relieved and lent—do not collect repayment; do not make the people pay this year's field tax.", idiomatic: "----4 In autumn, the eighth month, an edict said, \"Disasters were many in former years; this year silkworms and wheat were harmed. Do not collect repayment for the seed and food that were relieved and lent; do not make the people pay this year's field tax." },
  { zh: "」----5初，武帝征伐匈奴，深入窮追，二十餘年，匈奴馬畜孕重墮殰，罷極，苦之。", literal: "\" ----5 At the outset, Emperor Wu campaigned against the Xiongnu, driving deep in relentless pursuit for more than twenty years; the Xiongnu's horses and livestock, pregnant and heavy, miscarried and perished; exhausted to the limit, they suffered bitterly.", idiomatic: "\" ----5 At the outset Emperor Wu campaigned against the Xiongnu, driving deep in relentless pursuit for more than twenty years; Xiongnu horses and livestock, pregnant and heavy, miscarried and perished; exhausted to the limit, they suffered bitterly." },
  { zh: "常有欲和親意，未能得。", literal: "They often had the intent to seek heqin peace but could not achieve it.", idiomatic: "They often wished for heqin peace but could not achieve it." },
  { zh: "狐鹿孤單于有異母弟為左大都尉，賢，國人鄉之，母閼氏恐單于不立子而立左大都尉也，乃私使殺之。", literal: "The chanyu Hulu Gu had a younger half-brother who was Left Grand Commandant, worthy; the people of the state looked toward him. The chanyu's mother, the Yanzhi consort, feared the chanyu would not establish his son but would establish the Left Grand Commandant, and secretly had him killed.", idiomatic: "Chanyu Hulu Gu had a younger half-brother who was Left Grand Commandant and worthy; the people looked toward him. The chanyu's mother, the Yanzhi consort, feared the chanyu would not establish his son but would establish the Left Grand Commandant, and secretly had him killed." },
  { zh: "左大都尉同母兄怨，遂不肯復會單于庭。", literal: "The Left Grand Commandant's elder brother by the same mother bore resentment and thereupon refused to attend the chanyu's court again.", idiomatic: "The Left Grand Commandant's elder brother by the same mother bore resentment and refused to attend the chanyu's court again." },
  { zh: "是歲，單于病且死，謂諸貴人：「我子少，不能治國，立弟右谷蠡王。", literal: "That year the chanyu was ill and near death; he told the nobles: \"My son is young and cannot govern the state; establish my younger brother, the Right Guli King.", idiomatic: "That year the chanyu was ill and near death; he told the nobles, \"My son is young and cannot govern the state; establish my younger brother, the Right Guli King." },
  { zh: "」及單于死，衛律等與顓渠閼氏謀，匿其喪，矯單于令，更立子左谷蠡王為壺衍鞮單于。", literal: "\" When the chanyu died, Wei Lü and others plotted with Zhuanqu Yanzhi, concealed his death, forged the chanyu's command, and instead established his son, the Left Guli King, as chanyu Huyandi.", idiomatic: "\" When the chanyu died, Wei Lü and others plotted with Zhuanqu Yanzhi, concealed his death, forged the chanyu's command, and instead established his son, the Left Guli King, as Chanyu Huyandi." },
  { zh: "左賢王、右谷蠡王怨望，率其眾欲南歸漢，恐不能自致，即脅盧屠王，欲與西降烏孫。", literal: "The Left Worthy King and the Right Guli King harbored resentment; they led their followers wishing to return south to Han, fearing they could not reach it on their own, and thereupon coerced the Lutu King, intending to descend west and surrender to the Wusun.", idiomatic: "The Left Worthy King and the Right Guli King harbored resentment; they led their followers wishing to return south to Han, fearing they could not reach it on their own, and coerced the Lutu King, intending to surrender west to the Wusun." },
  { zh: "盧屠王告之單于，使人驗問，右谷蠡王不服，反以其罪罪盧屠王，國人皆冤之。", literal: "The Lutu King reported it to the chanyu; men were sent to investigate and question. The Right Guli King would not submit and instead charged the Lutu King with that very crime; the people of the state all considered it unjust.", idiomatic: "The Lutu King reported it to the chanyu; investigators were sent. The Right Guli King would not submit and instead charged the Lutu King with that very crime; the people all considered it unjust." },
  { zh: "於是二王去居其所，不復肯會龍城，匈奴始衰。", literal: "Thereupon the two kings departed to dwell in their own places and would no longer attend at Dragon City; the Xiongnu began to decline.", idiomatic: "Thereupon the two kings departed to their own territories and would no longer attend at Dragon City; the Xiongnu began to decline." },
  { zh: "1春，二月，有星孛於西北。", literal: "1. In spring, the second month, a comet appeared in the northwest.", idiomatic: "1. In spring, the second month, a comet appeared in the northwest." },
  { zh: "----2冬，十一月，壬辰朔，日有食之。", literal: "----2 In winter, the eleventh month, on the first day renchen of the month, there was an eclipse of the sun.", idiomatic: "----2 In winter, the eleventh month, on the first day renchen of the month, there was a solar eclipse." },
  { zh: "----3初，霍光與上官桀相親善。", literal: "----3 At the outset, Huo Guang and Shangguan Jie were close and on good terms.", idiomatic: "----3 At the outset Huo Guang and Shangguan Jie were close and on good terms." },
  { zh: "光每休沐出，桀常代光入決事。", literal: "Whenever Guang took leave and went out, Jie would regularly enter in his place to decide affairs.", idiomatic: "Whenever Guang took leave and went out, Jie would regularly enter in his place to decide affairs." },
  { zh: "光女為桀子安妻，生女，年甫五歲，安欲因光內之宮中；", literal: "Guang's daughter was wife to Bo Zi'an; she bore a daughter just five years old. An wished through Guang to bring her into the palace;", idiomatic: "Guang's daughter was wife to Bo Zi'an; she bore a daughter just five years old. An wished through Guang to bring her into the palace;" },
  { zh: "光以為尚幼，不聽。", literal: "Guang thought her still too young and would not listen.", idiomatic: "Guang thought her still too young and refused." },
  { zh: "蓋長公主私近子客河間丁外人，安素與外人善，說外人曰：「安子容貌端正，誠因長主時得入為-{后}-，以臣父子在朝而有椒房之重，成之在於足下。", literal: "The Elder Princess of Gai privately favored her retainer Ding Wairen of Hejian; An had long been on good terms with Wairen and said to him: \"An's son is handsome in appearance; if he could truly enter the palace as -{后}- through the Elder Princess's favor, with my father and son in court possessing the weight of the empress chamber, success lies with you.", idiomatic: "The Elder Princess of Gai privately favored her retainer Ding Wairen of Hejian; An had long been friendly with Wairen and told him, \"An's son is handsome; if he could truly enter the palace as -{后}- through the Elder Princess's favor, with my father and son in court holding empress-chamber weight, success lies with you." },
  { zh: "漢家故事，常以列侯尚主，足下何憂不封侯乎！", literal: "Han house precedent often makes a ranked marquis marry a princess—what worry have you about not being enfeoffed as marquis!", idiomatic: "Han precedent often makes a ranked marquis marry a princess—why worry you will not be enfeoffed as marquis!" },
  { zh: "」外人喜，言於長主。", literal: "\" Wairen was pleased and spoke of it to the Elder Princess.", idiomatic: "\" Wairen was pleased and spoke of it to the Elder Princess." },
  { zh: "長主以為然，詔召安女入為倢伃，安為騎都尉。", literal: "The Elder Princess thought it right; by edict An's daughter was summoned to enter as Lady Jieyu, and An was made Commandant of the Cavalry.", idiomatic: "The Elder Princess agreed; by edict An's daughter was summoned to enter as Lady Jieyu, and An was made Commandant of the Cavalry." },
  { zh: "1春，三月，甲寅，立皇后上官氏，赦天下。", literal: "1. In spring, the third month, on jiayin, the Empress Shangguan was established and an amnesty was proclaimed for all under Heaven.", idiomatic: "1. In spring, the third month, on jiayin, Empress Shangguan was established and an amnesty was proclaimed for all under Heaven." },
  { zh: "----2西南夷姑繒、葉榆復反，遣水衡都尉呂辟胡將益州兵擊之。", literal: "----2 The southwestern Yi of Guzhang and Yeyu rebelled again; Chief Steward for Water and Parks Lü Pihu was sent leading Yizhou troops to attack them.", idiomatic: "----2 The southwestern Yi of Guzhang and Yeyu rebelled again; Chief Steward for Water and Parks Lü Pihu was sent with Yizhou troops to attack them." },
  { zh: "辟胡不進，蠻夷遂殺益州太守，乘勝與辟胡戰，士戰及溺死者四千餘人。", literal: "Pihu did not advance; the barbarians thereupon killed the Governor of Yizhou and, pressing their advantage, fought Pihu; soldiers killed in battle and drowned numbered more than four thousand.", idiomatic: "Pihu did not advance; the barbarians killed the Governor of Yizhou and, pressing their advantage, fought Pihu; more than four thousand soldiers were killed in battle or drowned." },
  { zh: "冬，遣大鴻臚田廣明擊之。", literal: "In winter, Grand Herald Tian Guangming was sent to attack them.", idiomatic: "In winter Grand Herald Tian Guangming was sent to attack them." },
  { zh: "----3廷尉李種坐故縱死罪棄市。", literal: "----3 Minister of Justice Li Zhong, convicted of knowingly releasing a capital offender, was abandoned in the marketplace.", idiomatic: "----3 Minister of Justice Li Zhong, convicted of knowingly releasing a capital offender, was executed in the marketplace." },
  { zh: "----4是歲，上官安為車騎將軍。", literal: "----4 That year, Shangguan An was made General of Chariots and Cavalry.", idiomatic: "----4 That year Shangguan An was made General of Chariots and Cavalry." },
  { zh: "1春，正月，追尊帝外祖趙父為順成侯。", literal: "1. In spring, the first month, the emperor's maternal grandfather, Father Zhao, was posthumously honored as Marquis of Shuncheng.", idiomatic: "1. In spring, the first month, the emperor's maternal grandfather, Father Zhao, was posthumously honored as Marquis of Shuncheng." },
  { zh: "順成侯有姊君姁，賜錢二百萬、奴婢、第宅以充實焉。", literal: "Marquis of Shuncheng had an elder sister, Junxu; she was granted two million cash, slaves and maidservants, and a mansion to enrich her establishment.", idiomatic: "Marquis of Shuncheng had an elder sister, Junxu; she was granted two million cash, slaves and maidservants, and a mansion to enrich her establishment." },
  { zh: "諸昆弟各以親疏受賞賜，無在位者。", literal: "The various brothers and sisters each received rewards according to closeness of kin; none held office.", idiomatic: "The various siblings each received rewards according to closeness of kin; none held office." },
  { zh: "----2有男子乘黃犢車詣北闕，自謂衛太子；", literal: "----2 A man riding a yellow calf-drawn carriage came to the Northern Gate Tower and declared himself the Heir of Wei;", idiomatic: "----2 A man riding a yellow calf-drawn carriage came to the Northern Gate Tower and declared himself Crown Prince Wei;" },
  { zh: "公車以聞。", literal: "the Imperial Carriage Office reported it.", idiomatic: "the Imperial Carriage Office reported it." },
  { zh: "詔使公、卿、將軍、中二千石雜識視。", literal: "An edict ordered the dukes, ministers, generals, and officials at two thousand bushels and above jointly to identify and examine him.", idiomatic: "An edict ordered dukes, ministers, generals, and officials at two thousand bushels and above jointly to identify and examine him." },
  { zh: "長安中吏民聚觀者數萬人。", literal: "Officials and commoners of Chang'an gathered to watch—tens of thousands.", idiomatic: "Tens of thousands of Chang'an officials and commoners gathered to watch." },
  { zh: "右將軍勒兵闕下以備非常。", literal: "The Right General arrayed troops below the gate tower to guard against the unexpected.", idiomatic: "The Right General arrayed troops below the gate tower to guard against the unexpected." },
  { zh: "丞相、御史、中二千石至者並莫敢發言。", literal: "The chancellor, censor, and officials at two thousand bushels and above who arrived all did not dare speak.", idiomatic: "The chancellor, censor, and officials at two thousand bushels and above who arrived all dared not speak." },
  { zh: "京兆尹不疑後到，叱從吏收縛。", literal: "Metropolitan Commandant Buyi arrived later and shouted at his attending clerks to seize and bind him.", idiomatic: "Metropolitan Commandant Buyi arrived later and shouted at his clerks to seize and bind him." },
  { zh: "或曰：「是非未可知，且安之。", literal: "Someone said: \"Whether this is true or false is not yet known; for now let him be at ease.", idiomatic: "Someone said, \"Whether this is true or false is not yet known; for now let him be." },
  { zh: "」不疑曰：「諸君何患於衛太子！", literal: "\" Buyi said: \"Why do you gentlemen worry about the Heir of Wei!", idiomatic: "\" Buyi said, \"Why do you gentlemen worry about Crown Prince Wei!" },
  { zh: "昔蒯聵違命出奔，輒距而不納，《春秋》是之。", literal: "In former times Kuai Kui disobeyed orders and fled abroad; Ji Zhe barred him and would not admit him—the Spring and Autumn Annals approves this.", idiomatic: "In former times Kuai Kui disobeyed orders and fled abroad; Ji Zhe barred him and would not admit him—the Spring and Autumn Annals approves this." },
  { zh: "衛太子得罪先帝，亡不即死，今來自詣，此罪人也！", literal: "The Heir of Wei offended the former emperor, fled and did not die at once; now he has come of his own accord—this man is a criminal!", idiomatic: "Crown Prince Wei offended the former emperor, fled and did not die at once; now he has come of his own accord—this man is a criminal!" },
  { zh: "」遂送詔獄。", literal: "\" He was thereupon sent to the imperial prison under edict.", idiomatic: "\" He was thereupon sent to the imperial prison under edict." },
  { zh: "天子與大將軍霍光聞而嘉之曰：「公卿大臣當用有經術、明於大誼者。", literal: "The Son of Heaven and Grand General Huo Guang heard of it and praised him, saying: \"Dukes, ministers, and great officials ought to employ those versed in the classics and clear on great principle.", idiomatic: "The emperor and Grand General Huo Guang heard of it and praised him, saying, \"Dukes, ministers, and great officials ought to employ those versed in the classics and clear on great principle." },
  { zh: "」繇是不疑名聲重於朝廷，在位者皆自以不及也。", literal: "\" From this Buyi's reputation weighed heavy in court; those in office all considered themselves his inferior.", idiomatic: "\" From this Buyi's reputation weighed heavy at court; those in office all considered themselves his inferior." },
  { zh: "廷尉驗治何人，竟得奸詐，本夏陽人，姓成，名方遂，居湖，以卜筮為事。", literal: "The Minister of Justice investigated and tried: who was this man? At last the fraud was obtained. He was originally a man of Xiayang, surname Cheng, personal name Fang Sui, dwelling at Hu, who made divination by milfoil and tortoise his trade.", idiomatic: "The Minister of Justice investigated: who was this man? At last the fraud was exposed. He was originally from Xiayang, surname Cheng, personal name Fang Sui, living at Hu, who made his living by divination." },
  { zh: "有故太子舍人嘗從方遂卜，謂曰：「子狀貌甚似衛太子。", literal: "A former Palace Attendant of the heir had once had Fang Sui divine for him and said to him: \"Your appearance greatly resembles the Heir of Wei.", idiomatic: "A former crown prince's palace attendant had once had Fang Sui divine for him and said, \"Your appearance greatly resembles Crown Prince Wei." },
  { zh: "」方遂心利其言，冀得以富貴。", literal: "\" Fang Sui's heart profited by his words and hoped thereby to gain wealth and rank.", idiomatic: "\" Fang Sui's heart seized on his words and hoped thereby to gain wealth and rank." },
  { zh: "坐誣罔不道，要斬。", literal: "Convicted of false accusation and impiety, he was beheaded at the waist.", idiomatic: "Convicted of false accusation and impiety, he was beheaded at the waist." },
  { zh: "----3夏，六月，封上官安為桑樂侯。", literal: "----3 In summer, the sixth month, Shangguan An was enfeoffed as Marquis of Sangle.", idiomatic: "----3 In summer, the sixth month, Shangguan An was enfeoffed as Marquis of Sangle." },
  { zh: "安日以驕淫，受賜殿中，對賓客言：「與我婿飲，大樂！", literal: "An daily grew arrogant and dissolute; receiving gifts in the palace hall, he said to guests: \"Drink with my son-in-law—great joy!", idiomatic: "An grew daily more arrogant and dissolute; receiving gifts in the palace hall, he said to guests, \"Drink with my son-in-law—what joy!" },
  { zh: "」見其服飾，使人歸，欲自燒物。", literal: "\" Seeing their clothing and adornments, he had people return home, wishing to burn their possessions.", idiomatic: "\" Seeing their clothing and adornments, he had people go home, intending to burn their possessions." },
  { zh: "子病死，仰而罵天。", literal: "When his son died of illness, he looked up and cursed Heaven.", idiomatic: "When his son died of illness, he looked up and cursed Heaven." },
  { zh: "其頑悖如此。", literal: "His obstinate perversity was like this.", idiomatic: "His obstinate perversity was like this." },
  { zh: "----4罷儋耳、真番郡。", literal: "----4 The Dan'er and Zhenfan commanderies were abolished.", idiomatic: "----4 The Dan'er and Zhenfan commanderies were abolished." },
  { zh: "----5秋，大鴻臚廣明、軍正王平擊益州，斬首、捕虜三萬餘人，獲畜產五萬餘頭。", literal: "----5 In autumn, Grand Herald Guangming and Army Rectifier Wang Ping attacked Yizhou; heads cut off and captives taken exceeded thirty thousand, and livestock obtained exceeded fifty thousand head.", idiomatic: "----5 In autumn, Grand Herald Guangming and Army Rectifier Wang Ping attacked Yizhou, beheading and capturing more than thirty thousand men and taking more than fifty thousand head of livestock." },
  { zh: "----6諫大夫杜延年見國家承武帝奢侈、師旅之後，數為大將軍光言：「年歲比不登，流民未盡還，宜修孝文時政，示以儉約、寬和，順天心，說民意，年歲宜應。", literal: "----6 Remonstrance Grandee Du Yannian, seeing the state inherit Emperor Wu's extravagance and campaigns, repeatedly spoke to Grand General Guang: \"Years in succession have not had good harvests; displaced people have not all returned—it is fitting to restore Emperor Wen's policies, show frugality and restraint and lenience and harmony, accord with Heaven's heart, please the people's intent, and the years ought to respond.", idiomatic: "----6 Remonstrance Grandee Du Yannian, seeing the state inherit Emperor Wu's extravagance and campaigns, repeatedly told Grand General Guang, \"Harvests have failed year after year and displaced people have not all returned. It is fitting to restore Emperor Wen's policies, show frugality, restraint, lenience, and harmony, accord with Heaven's heart, please the people, and the years ought to respond." },
  { zh: "」光納其言。", literal: "\" Guang accepted his words.", idiomatic: "\" Guang accepted his counsel." },
  { zh: "延年，故御史大夫周之子也。", literal: "Yannian was a son of the former Censor-in-Chief Zhou.", idiomatic: "Yannian was a son of the former Censor-in-Chief Du Zhou." },
  { zh: "1春，二月，詔有司問郡國所舉賢良、文學，民所疾苦、教化之要，皆對：「願罷鹽、鐵、酒榷、均輸官，毋與天下爭利，示以儉節，然後教化可興。", literal: "1 In spring, the second month, an edict had the responsible offices question the worthy and learned men recommended by commanderies and kingdoms on the people's hardships and essentials of instruction and transformation; all replied: \"We wish to abolish the salt, iron, wine monopoly, and equalizing transport offices, not contend with all under Heaven for profit, show frugality and restraint, and only then can instruction and transformation be raised.", idiomatic: "1 In spring, the second month, an edict had the responsible offices question the worthy and learned men recommended by commanderies and kingdoms on the people's hardships and the essentials of moral instruction. All replied, \"We wish to abolish the salt, iron, wine monopoly, and equalizing transport offices, stop contending with all under Heaven for profit, show frugality and restraint, and only then can moral instruction flourish." },
  { zh: "」桑弘羊難，以為：「此國家大業，所以制四夷，安邊足用之本，不可廢也。", literal: "\" Sang Hongyang objected, holding: \"This is the state's great enterprise, the foundation for controlling the four barbarians and securing the borders with sufficient resources—it cannot be abolished.", idiomatic: "\" Sang Hongyang objected, saying, \"This is the state's great enterprise, the foundation for controlling the four barbarians and securing the borders with sufficient resources—it cannot be abolished." },
  { zh: "」於是鹽鐵之議起焉。", literal: "\" Thereupon the salt-and-iron debate arose.", idiomatic: "\" Thereupon the salt-and-iron debate arose." },
  { zh: "----2初，蘇武既徙北海上，稟食不至，掘野鼠、去草實而食之。", literal: "----2 At first, after Su Wu had been relocated to the North Sea coast, allotted food did not arrive; he dug wild rats and removed grass seeds and ate them.", idiomatic: "----2 At first, after Su Wu had been relocated to the North Sea coast, allotted food did not arrive; he dug up wild rats and stripped grass seeds to eat." },
  { zh: "杖漢節牧羊，臥起操持，節旄盡落。", literal: "Leaning on the Han staff of office he herded sheep; lying down and rising he held it in hand—the tassels on the staff all fell off.", idiomatic: "Leaning on the Han staff of office he herded sheep; whether lying down or rising he held it in hand, until the tassels on the staff had all fallen off." },
  { zh: "武在漢，與李陵俱為侍中；", literal: "Wu in Han had together with Li Ling served as Palace Attendant;", idiomatic: "In Han, Wu and Li Ling had both served as Palace Attendants;" },
  { zh: "陵降匈奴，不敢求武。", literal: "Ling surrendered to the Xiongnu and did not dare seek Wu.", idiomatic: "Ling surrendered to the Xiongnu and did not dare seek out Wu." },
  { zh: "久之，單于使陵至海上，為武置酒設樂，因謂武曰：「單于聞陵與子卿素厚，故使來說足下，虛心欲相待，終不得歸漢，空自苦；", literal: "After long time the Chanyu sent Ling to the sea coast, set out wine and music for Wu, and thereby said to Wu: \"The Chanyu heard Ling and Ziqing were always close, therefore sent me to persuade you, my lord—the heart is open and wishes to treat you well; in the end you cannot return to Han and vainly suffer yourself;", idiomatic: "After a long time the Chanyu sent Ling to the sea coast, set out wine and music for Wu, and said to him, \"The Chanyu heard that Ling and Ziqing were always close, and therefore sent me to persuade you, my lord. His heart is open and he wishes to treat you well, but in the end you cannot return to Han and only suffer in vain;" },
  { zh: "亡人之地，信義安所見乎！", literal: "in a land of lost men, where is faith and righteousness to be shown!", idiomatic: "in a land of lost men, where is faith and righteousness to be shown!" },
  { zh: "足下兄弟二人，前皆坐事自殺；", literal: "Your lordship's two brothers before both sat convicted of offenses and killed themselves;", idiomatic: "Your lordship's two brothers were both earlier convicted of offenses and killed themselves;" },
  { zh: "來時，太夫人已不幸；", literal: "when you came, the Grand Lady had already met misfortune;", idiomatic: "when you came, your mother had already died;" },
  { zh: "子卿婦年少，聞已更嫁矣；", literal: "Ziqing's wife is young—I hear she has already remarried;", idiomatic: "Ziqing's wife is young—I hear she has already remarried;" },
  { zh: "獨有女弟二人、兩女、一男，今復十餘年，存亡不可知。", literal: "only two younger sisters, two daughters, and one son remain; now again more than ten years—whether alive or dead cannot be known.", idiomatic: "only two younger sisters, two daughters, and one son remain; now more than ten years have passed again, and whether they live or die cannot be known." },
  { zh: "人生如朝露，何久自苦如此！", literal: "Human life is like morning dew—why long suffer yourself like this!", idiomatic: "Human life is like morning dew—why long suffer yourself like this!" },
  { zh: "陵始降時，忽忽如狂，自痛負漢，加以老母系保宮。", literal: "When Ling first surrendered, he was restless as if mad, himself pained at having failed Han, and moreover his old mother was detained in the protection palace.", idiomatic: "When Ling first surrendered, he was restless as if mad, pained at having failed Han, and moreover his old mother was detained in the protection palace." },
  { zh: "子卿不欲降，何以過陵！", literal: "Ziqing does not wish to surrender—how does he surpass Ling!", idiomatic: "Ziqing does not wish to surrender—how are you better than Ling!" },
  { zh: "且陛下春秋高，法令無常，大臣無罪夷滅者數十家。", literal: "Moreover the emperor's years are advanced, laws and orders are without constancy, and great ministers without guilt exterminated root and branch number several tens of families.", idiomatic: "Moreover the emperor is advanced in years, laws and orders are erratic, and several tens of families of guiltless great ministers have been exterminated root and branch." },
  { zh: "安危不可知，子卿尚復誰為乎！", literal: "Safety and danger cannot be known—Ziqing, for whom do you still act!", idiomatic: "Safety and danger cannot be known—for whom do you still act, Ziqing!" },
  { zh: "」武曰：「武父子無功德，皆為陛下所成就，位列將，爵通侯，兄弟親近，常願肝腦塗地。", literal: "\" Wu said: \"Wu father and son had no merit or virtue—all were accomplished by Your Majesty; we ranked as generals, enfeoffed as full marquises, brothers close and near, and constantly wished to smear liver and brain on the ground.", idiomatic: "\" Wu said, \"Wu father and son had no merit—all was accomplished by Your Majesty. We ranked as generals, were enfeoffed as full marquises, and as close brothers constantly wished to lay down our lives." },
  { zh: "今得殺身自效，雖斧鉞、湯鑊，誠甘樂之！", literal: "Now obtaining to kill the body and devote effect, though axe and halberd, boiling cauldron, truly I would gladly enjoy it!", idiomatic: "Now to be able to give my life in service, though it be axe and halberd or boiling cauldron, I would truly and gladly accept it!" },
  { zh: "臣事君，猶子事父也。", literal: "A subject serving his lord is like a son serving his father.", idiomatic: "A subject serving his lord is like a son serving his father." },
  { zh: "子為父死，無所恨。", literal: "A son dying for his father has nothing to regret.", idiomatic: "A son dying for his father has nothing to regret." },
  { zh: "願勿復再言！", literal: "I wish you would not speak again!", idiomatic: "Please do not speak of this again!" },
  { zh: "」陵與武飲數日，復曰：「子卿壹聽陵言！", literal: "\" Ling drank with Wu for several days, then again said: \"Ziqing, wholly listen to Ling's words!", idiomatic: "\" Ling drank with Wu for several days, then again said, \"Ziqing, please wholly heed my words!" },
  { zh: "」武曰：「自分已死久矣，王必欲降武，請畢今日之歡，效死於前！", literal: "\" Wu said: \"I myself have judged myself dead long ago. If the king must have Wu surrender, please finish today's pleasure and I will devote death before you!", idiomatic: "\" Wu said, \"I have long considered myself dead. If you must have Wu surrender, please finish today's pleasure and I will die before you!" },
  { zh: "」陵見其至誠，喟然歎曰：「嗟乎，義士！", literal: "\" Ling saw his utmost sincerity and sighed with emotion: \"Alas, a man of righteousness!", idiomatic: "\" Ling saw his utmost sincerity and sighed with emotion, \"Alas, a man of righteousness!" },
  { zh: "陵與衛律之罪上通於天！", literal: "Ling's and Wei Lü's guilt reaches up to Heaven!", idiomatic: "Ling's and Wei Lü's guilt reaches up to Heaven!" },
  { zh: "」因泣下沾衿，與武決去。", literal: "\" Thereupon tears fell and soaked his collar; he took leave of Wu and departed.", idiomatic: "\" Thereupon tears fell and soaked his collar; he took leave of Wu and departed." },
  { zh: "賜武牛羊數十頭。", literal: "He bestowed on Wu several tens of cattle and sheep.", idiomatic: "He bestowed on Wu several tens of cattle and sheep." },
  { zh: "後陵復至北海上，語武以武帝崩。", literal: "Later Ling again came to the North Sea coast and told Wu that Emperor Wu had died.", idiomatic: "Later Ling again came to the North Sea coast and told Wu that Emperor Wu had died." },
  { zh: "武南鄉號哭歐血，旦夕臨，數月。", literal: "Wu faced south and wailed, vomiting blood; morning and evening he faced the direction in mourning for several months.", idiomatic: "Wu faced south and wailed until he vomited blood; morning and evening he faced south in mourning for several months." },
  { zh: "及壺衍鞮單于立，母閼氏不正，國內乖離，常恐漢兵襲之，於是衛律為單于謀，與漢和親。", literal: "When Chanyu Huyanshidi was established, the mother's yanzhi was not correct, the state within was divided and estranged, and they constantly feared Han troops would strike them; thereupon Wei Lü schemed for the Chanyu and made peace kinship with Han.", idiomatic: "When Chanyu Huyanshidi was established, the queen mother's position was irregular, the state was divided within, and they constantly feared Han troops would strike; thereupon Wei Lü schemed for the Chanyu and sought peace kinship with Han." },
  { zh: "漢使至，求蘇武等，匈奴詭言武死。", literal: "Han envoys arrived and sought Su Wu and the rest; the Xiongnu falsely said Wu was dead.", idiomatic: "Han envoys arrived and sought Su Wu and the rest; the Xiongnu falsely claimed Wu was dead." },
  { zh: "後漢使復至匈奴，常惠私見漢使，教使者謂單于，言：「天子射上林中，得雁，足有系帛書，言武等在某澤中。", literal: "Later Han envoys again reached the Xiongnu; Chang Hui privately saw the Han envoy and taught the envoy to tell the Chanyu, saying: \"The Son of Heaven shot in Shanglin Park and obtained a wild goose; on its foot was tied a silk book saying Wu and the rest are in a certain marsh.", idiomatic: "Later Han envoys again reached the Xiongnu; Chang Hui privately met the Han envoy and taught him to tell the Chanyu, saying, \"The emperor shot in Shanglin Park and obtained a wild goose; on its foot was tied a silk message saying Wu and the rest are in a certain marsh." },
  { zh: "」使者大喜，如惠語以讓單于。", literal: "\" The envoy was greatly pleased and, as Hui's words directed, reproached the Chanyu.", idiomatic: "\" The envoy was greatly pleased and, as Hui had said, reproached the Chanyu." },
  { zh: "單于視左右而驚，謝漢使曰：「武等實在。", literal: "The Chanyu looked left and right in alarm and apologized to the Han envoy: \"Wu and the rest truly exist.", idiomatic: "The Chanyu looked left and right in alarm and apologized to the Han envoy, \"Wu and the rest truly still live." },
  { zh: "」乃歸武及馬宏等。", literal: "\" Thereupon he returned Wu and Ma Hong and the rest.", idiomatic: "\" Thereupon he returned Wu and Ma Hong and the rest." },
  { zh: "馬宏者，前副光祿大夫王忠使西國，為匈奴所遮；", literal: "Ma Hong was formerly deputy to Palace Illustrious Grandee Wang Zhong on a mission to western states and was intercepted by the Xiongnu;", idiomatic: "Ma Hong had formerly been deputy to Palace Illustrious Grandee Wang Zhong on a mission to western states and was intercepted by the Xiongnu;" },
  { zh: "忠戰死，馬宏生得，亦不肯降。", literal: "Zhong died in battle; Ma Hong was taken alive and also would not surrender.", idiomatic: "Zhong died in battle; Ma Hong was taken alive and also would not surrender." },
  { zh: "故匈奴歸此二人，欲以通善意。", literal: "Therefore the Xiongnu returned these two men, wishing thereby to open good intent.", idiomatic: "Therefore the Xiongnu returned these two men, wishing thereby to signal good intent." },
  { zh: "於是李陵置酒賀武曰：「今足下還歸，揚名於匈奴，功顯於漢室，雖古竹帛所載，丹青所畫，何以過子卿！", literal: "Thereupon Li Ling set out wine to congratulate Wu, saying: \"Now your lordship returns home, fame raised among the Xiongnu, merit displayed in the Han house—even what ancient bamboo and silk record and red and green paint, how could they surpass Ziqing!", idiomatic: "Thereupon Li Ling set out wine to congratulate Wu, saying, \"Now your lordship returns home, your fame raised among the Xiongnu and your merit displayed in the Han house—even what ancient bamboo and silk record and paintings depict, how could they surpass Ziqing!" },
  { zh: "陵雖駑怯，令漢貰陵罪，全其老母，使得奮大辱之積志，庶幾乎曹柯之盟，此陵宿昔之所不忘也。", literal: "Ling though dull and timid—if Han would pardon Ling's guilt, preserve his old mother, and let him be able to exert the long-accumulated will of great disgrace, perhaps like the Cao Ke covenant—this Ling from old nights has not forgotten.", idiomatic: "Ling is dull and timid, but if Han would pardon Ling's guilt, preserve his old mother, and let him exert the will long accumulated from great disgrace, perhaps like the covenant at Cao Ke—this Ling has never forgotten from of old." },
  { zh: "收族陵家，為世大戮，陵尚復何顧乎！", literal: "His clan was gathered and exterminated—an age's great punishment—what does Ling still care for!", idiomatic: "His clan was gathered and exterminated—the age's great punishment—what does Ling still care for!" },
  { zh: "已矣，令子卿知吾心耳！", literal: "It is done—let Ziqing know my heart!", idiomatic: "It is done—let Ziqing know my heart!" },
  { zh: "」陵泣下數行，因與武決。", literal: "\" Ling wept several lines of tears and thereupon took leave of Wu.", idiomatic: "\" Ling wept several lines of tears and thereupon took leave of Wu." },
  { zh: "單于召會武官屬，前已降及物故，凡隨武還者九人。", literal: "The Chanyu summoned and assembled Wu's official subordinates; those who had earlier surrendered and those who had died—in all nine followed Wu back.", idiomatic: "The Chanyu summoned and assembled Wu's official subordinates; counting those who had earlier surrendered and those who had died, in all nine followed Wu back." },
  { zh: "既至京師，詔武奉一太牢謁武帝園廟，拜為典屬國，秩中二千石，賜錢二百萬，公田二頃，宅一區。", literal: "Once they reached the capital, an edict had Wu offer one grand sacrificial victim and visit Emperor Wu's park temple; he was appointed Director of Dependent States, rank middle two thousand dan, bestowed two million cash, two qing of public fields, and one residence.", idiomatic: "Once they reached the capital, an edict had Wu offer a grand sacrificial victim and visit Emperor Wu's park temple; he was appointed Director of Dependent States at rank of middle two thousand dan, bestowed two million cash, two qing of public fields, and one residence." },
  { zh: "武留匈奴凡十九歲，始以強壯出，及還，鬚髮盡白。", literal: "Wu remained among the Xiongnu in all nineteen years; he went forth in his prime strength, and on return his beard and hair were all white.", idiomatic: "Wu remained among the Xiongnu nineteen years in all; he had gone forth in his prime, and on return his beard and hair were all white." },
  { zh: "霍光、上官桀與李陵素善，遣陵故人隴西任立政等三人俱至匈奴招之。", literal: "Huo Guang, Shangguan Jie, and Li Ling had always been on good terms; they sent Ling's old acquaintance Ren Lizheng of Longxi and three others together to the Xiongnu to summon him.", idiomatic: "Huo Guang, Shangguan Jie, and Li Ling had always been on good terms; they sent Ling's old acquaintance Ren Lizheng of Longxi and three others together to the Xiongnu to summon him." },
  { zh: "陵曰：「歸易耳，丈夫不能再辱！", literal: "Ling said: \"Returning is easy—but a man cannot suffer disgrace twice!", idiomatic: "Ling said, \"Returning is easy, but a man cannot suffer disgrace twice!" },
  { zh: "」遂死於匈奴。", literal: "\" Thereupon he died among the Xiongnu.", idiomatic: "\" Thereupon he died among the Xiongnu." },
  { zh: "----3夏，旱。", literal: "----3 In summer, drought.", idiomatic: "----3 In summer, there was drought." },
  { zh: "----4秋，七月，罷榷酤官，從賢良、文學之議也。", literal: "----4 In autumn, the seventh month, the wine monopoly offices were abolished, following the counsel of the worthy and learned.", idiomatic: "----4 In autumn, the seventh month, the wine monopoly offices were abolished, following the counsel of the worthy and learned." },
  { zh: "武帝之末，海內虛耗，戶口減半，霍光知時務之要，輕徭薄賦，與民休息。", literal: "At the end of Emperor Wu's reign, within the seas was empty and depleted and household registers were halved; Huo Guang knew the essentials of the times' affairs, lightened corvée and reduced levies, and gave the people rest.", idiomatic: "At the end of Emperor Wu's reign the realm was depleted and household registers were halved; Huo Guang knew the essentials of the times, lightened corvée and reduced levies, and gave the people rest." },
  { zh: "至是匈奴和親，百姓充實，稍復文、景之業焉。", literal: "By this time the Xiongnu made peace kinship, the common people were full and solid, and they slightly restored the enterprises of Emperors Wen and Jing.", idiomatic: "By this time the Xiongnu made peace kinship, the common people were prosperous, and the realm slightly restored the achievements of Emperors Wen and Jing." },
  { zh: "----5詔以鉤町侯毋波率其邑君長、人民擊反者有功，立以為鉤町王。", literal: "----5 An edict because Marquis of Goujing Wubo led his town chiefs and elders and people to strike rebels with merit established him as King of Goujing.", idiomatic: "----5 An edict, because Marquis of Goujing Wubo had led his town chiefs, elders, and people to strike rebels with merit, established him as King of Goujing." },
  { zh: "賜田廣明爵關內侯。", literal: "Tian Guangming was bestowed the noble rank of Marquis within the Passes.", idiomatic: "Tian Guangming was bestowed the noble rank of Marquis within the Passes." },
  { zh: "1春，武都氐人反，遣執金吾馬適建、龍額侯韓增、大鴻臚田廣明將三輔、太常徒，皆免刑，擊之。", literal: "1 In spring, the Di of Wudu rebelled; the emperor sent Commandant of Justice Ma Shi Jian, Marquis of Long'e Han Zeng, and Grand Herald Tian Guangming to lead Metropolitan Area and Grand Master of Ceremonies convicts, all exempted from punishment, to attack them.", idiomatic: "1 In spring, the Di of Wudu rebelled; he sent Commandant of Justice Ma Shi Jian, Marquis of Long'e Han Zeng, and Grand Herald Tian Guangming to lead Metropolitan Area and Grand Master of Ceremonies convicts, all exempted from punishment, to attack them." },
  { zh: "----2夏，六月，赦天下。", literal: "----2 In summer, the sixth month, amnesty throughout all under Heaven.", idiomatic: "----2 In summer, the sixth month, amnesty was proclaimed throughout the realm." },
  { zh: "----3秋，七月，乙亥晦，日有食之，既。", literal: "----3 In autumn, the seventh month, on the last day of the month yihai, there was a solar eclipse—it was total.", idiomatic: "----3 In autumn, the seventh month, on the last day of the month yihai, there was a total solar eclipse." },
  { zh: "----4八月，改元。", literal: "----4 In the eighth month, the era name was changed.", idiomatic: "----4 In the eighth month, the era name was changed." },
  { zh: "----5上官桀父子既尊，盛德長公主，欲為丁外人求封侯，霍光不許。", literal: "----5 After Shangguan Jie father and son had been honored, they greatly indebted the Princess of Gai and wished to seek enfeoffment as marquis for Ding the outsider; Huo Guang did not assent.", idiomatic: "----5 After Shangguan Jie father and son had been honored, they greatly indebted the Princess of Gai and sought enfeoffment as marquis for Ding the outsider; Huo Guang refused." },
  { zh: "又為外人求光祿大夫，欲令得召見，又不許。", literal: "Again they sought Palace Illustrious Grandee for the outsider, wishing to let him obtain audience—they were again not assented.", idiomatic: "Again they sought Palace Illustrious Grandee for the outsider, wishing to let him obtain audience, and were again refused." },
  { zh: "長主大以是怨光，而桀、安數為外人求官爵弗能得，亦慚。", literal: "The princess greatly for this resented Guang, while Jie and An repeatedly sought offices and noble ranks for the outsider and could not obtain them—they also were ashamed.", idiomatic: "The princess greatly resented Guang for this, while Jie and An repeatedly sought offices and noble ranks for the outsider without success and were also ashamed." },
  { zh: "又桀妻父所幸充國為太醫監，闌入殿中，下獄當死；", literal: "Moreover Jie's wife's father, the favored Chongguo, was Grand Physician Superintendent and unlawfully entered the palace hall; sent down to prison he ought to die;", idiomatic: "Moreover Jie's wife's father, the favored Chongguo, was Grand Physician Superintendent and unlawfully entered the palace hall; imprisoned, he was liable to death;" },
  { zh: "冬月且盡，蓋主為充國入馬二十匹贖罪，乃得減死論。", literal: "the winter month was nearly ended; the Princess of Gai for Chongguo presented twenty horses to redeem guilt, and only then obtained reduced death sentence.", idiomatic: "the winter month was nearly ended; the Princess of Gai presented twenty horses on Chongguo's behalf to redeem his guilt, and only then obtained a reduced sentence short of death." },
  { zh: "於是桀、安父子深怨光而重德蓋主。", literal: "Thereupon Jie and An father and son deeply resented Guang and greatly indebted the Princess of Gai.", idiomatic: "Thereupon Jie and An father and son deeply resented Guang and were deeply indebted to the Princess of Gai." },
  { zh: "自先帝時，桀已為九卿，位在光右，及父子並為將軍，皇后親安女，光乃其外祖，而顧專制朝事，由是與光爭權。", literal: "From the former emperor's time Jie was already one of the Nine Ministers, rank to Guang's right; when father and son together were generals, the empress was close kin to An's daughter, and Guang was their maternal grandfather—yet he turned to monopolize court affairs; because of this he contended for power with Guang.", idiomatic: "From the former emperor's time Jie was already one of the Nine Ministers, ranked above Guang; when father and son together were generals, the empress was close kin to An's daughter and Guang was their maternal grandfather—yet he turned to monopolize court affairs; because of this he contended for power with Guang." },
  { zh: "燕王旦自以帝兄不得立，常懷怨望。", literal: "Prince Dan of Yan, considering himself the emperor's elder brother and not established, constantly harbored resentment and longing.", idiomatic: "Prince Dan of Yan, considering himself the emperor's elder brother and not established as heir, constantly harbored resentment." },
  { zh: "及御史大夫桑弘羊建造酒榷、鹽、鐵，為國興利，伐其功，欲為子弟得官，亦怨恨光。", literal: "When Censor-in-Chief Sang Hongyang built the wine monopoly, salt, and iron to raise profit for the state, he boasted of his merit and wished his sons and younger brothers to obtain offices—he also resented Guang.", idiomatic: "When Censor-in-Chief Sang Hongyang built the wine monopoly, salt, and iron to raise profit for the state, he boasted of his merit and wished his sons and younger brothers to obtain offices, and also resented Guang." },
  { zh: "於是蓋主、桀、安、弘羊皆與旦通謀。", literal: "Thereupon the Princess of Gai, Jie, An, and Hongyang all communicated in conspiracy with Dan.", idiomatic: "Thereupon the Princess of Gai, Jie, An, and Hongyang all entered into conspiracy with Dan." },
  { zh: "旦遣孫縱之等前後十餘輩，多賫金寶、走馬賂遺蓋主、桀、弘羊等。", literal: "Dan sent Sun Zongzhi and others in more than ten parties before and after, mostly bearing gold and treasures and swift horses as bribes to the Princess of Gai, Jie, Hongyang, and the rest.", idiomatic: "Dan sent Sun Zongzhi and others in more than ten parties before and after, mostly bearing gold, treasures, and swift horses as bribes to the Princess of Gai, Jie, Hongyang, and the rest." },
  { zh: "桀等又詐令人為燕王上書，言：「光出都肄郎、羽林，道上稱蹕，太官先置。", literal: "Jie and the rest also falsely had someone submit a memorial as from the Prince of Yan, saying: \"Guang when leaving the capital drilled Gentlemen of the Palace and Feathered Forest; on the road he proclaimed the imperial progress halt, and the Grand Provisioner was set out first.", idiomatic: "Jie and the rest also had someone falsely submit a memorial in the Prince of Yan's name, saying, \"When Guang leaves the capital he drills Gentlemen of the Palace and the Feathered Forest; on the road he proclaims the imperial progress halt, and the Grand Provisioner is set out first." },
  { zh: "」又引「蘇武使匈奴二十年不降，乃為典屬國；", literal: "\" He also cited \"Su Wu was envoy to the Xiongnu twenty years without surrendering, yet was made Director of Dependent States;", idiomatic: "\" He also cited, \"Su Wu was envoy to the Xiongnu twenty years without surrendering, yet was made Director of Dependent States;" },
  { zh: "大將軍長史敞無功，為搜粟都尉；", literal: "the Grand General's chief clerk Chang had no merit, yet was made Searcher of Grain Commandant;", idiomatic: "the Grand General's chief clerk Chang had no merit, yet was made Searcher of Grain Commandant;" },
  { zh: "又擅調益莫府校尉。", literal: "again on his own authority transferred and increased Grand Marshal's Office colonels.", idiomatic: "again on his own authority transferred and increased Grand Marshal's Office colonels." },
  { zh: "光專權自恣，疑有非常。", literal: "Guang monopolizes power and indulges himself—I suspect there is irregularity.", idiomatic: "Guang monopolizes power and indulges himself—I suspect irregular intent." },
  { zh: "臣旦願歸符璽，入宿衛，察奸臣變。", literal: "Your subject Dan wishes to return the tallies and seals, enter palace guard service, and investigate wicked ministers' changes.", idiomatic: "Your subject Dan wishes to return the tallies and seals, enter palace guard service, and investigate wicked ministers' plots." },
  { zh: "」候司光出沐日奏之，桀欲從中下其事，弘羊當與諸大臣共執退光。", literal: "\" They waited to memorialize on the day Guang went out to bathe; Jie wished to have the matter handled from the Central Secretariat down, and Hongyang ought together with the various great ministers to seize and remove Guang.", idiomatic: "\" They waited to memorialize on the day Guang went out to bathe; Jie wished to have the matter handled from the Central Secretariat down, and Hongyang was to join the various great ministers in seizing and removing Guang." },
  { zh: "書奏，帝不肯下。", literal: "The memorial was submitted; the emperor would not release it downward.", idiomatic: "The memorial was submitted; the emperor would not release it downward." },
  { zh: "明旦，光聞之，止畫室中不入。", literal: "The next dawn Guang heard and stopped in the painted chamber, not entering.", idiomatic: "The next morning Guang heard of it and stopped in the painted chamber, not entering court." },
  { zh: "上問：「大將軍安在？", literal: "The emperor asked: \"Where is the Grand General?", idiomatic: "The emperor asked, \"Where is the Grand General?" },
  { zh: "」左將軍桀對曰：「以燕王告其罪，故不敢入。", literal: "\" Left General Jie replied: \"Because the Prince of Yan reported his crimes, therefore he does not dare enter.", idiomatic: "\" Left General Jie replied, \"Because the Prince of Yan reported his crimes, he does not dare enter." },
  { zh: "」有詔：「召大將軍。", literal: "\" There was an edict: \"Summon the Grand General.", idiomatic: "\" There was an edict, \"Summon the Grand General." },
  { zh: "」光入，免冠、頓首謝。", literal: "\" Guang entered, removed his cap, and bowed his head in thanks.", idiomatic: "\" Guang entered, removed his cap, and bowed his head in thanks." },
  { zh: "上曰：「將軍冠！", literal: "The emperor said: \"General, put on your cap!", idiomatic: "The emperor said, \"General, put on your cap!" },
  { zh: "朕知是書詐也，將軍無罪。", literal: "I know this memorial is fraudulent—General, you are without guilt.", idiomatic: "I know this memorial is fraudulent—General, you are without guilt." },
  { zh: "」光曰：「陛下何以知之？", literal: "\" Guang said: \"Your Majesty, how do you know it?", idiomatic: "\" Guang said, \"Your Majesty, how do you know it?" },
  { zh: "」上曰：「將軍之廣明都郎，近耳；", literal: "\" The emperor said: \"The General's appointment of Guangming as Metropolitan Commandant of Gentlemen was recent;", idiomatic: "\" The emperor said, \"The general's appointment of Guangming as Metropolitan Commandant of Gentlemen was recent;" },
  { zh: "調校尉以來，未能十日，燕王何以得知之！", literal: "since transferring colonels, not yet ten days—how could the Prince of Yan know it!", idiomatic: "and since transferring colonels not ten days have passed—how could the Prince of Yan know it!" },
  { zh: "且將軍為非，不須校尉。", literal: "Moreover if the General did wrong, colonels would not be needed.", idiomatic: "Moreover if the general did wrong, colonels would not be needed." },
  { zh: "」是時帝年十四，尚書、左右皆驚。", literal: "\" At this time the emperor was fourteen; Masters of Writing and attendants left and right were all startled.", idiomatic: "\" At this time the emperor was fourteen; Masters of Writing and attendants left and right were all startled." },
  { zh: "而上書者果亡，捕之甚急。", literal: "The memorial-writer indeed fled; pursuit of him was very urgent.", idiomatic: "The memorial-writer indeed fled; pursuit of him was very urgent." },
  { zh: "桀等懼，白上：「小事不足遂。", literal: "Jie and others were afraid and reported to the emperor: \"A small matter is not worth pursuing to the end.", idiomatic: "Jie and others were afraid and reported to the emperor, \"A small matter is not worth pursuing to the end." },
  { zh: "」上不聽。", literal: "\" The emperor would not heed it.", idiomatic: "\" The emperor would not heed it." },
  { zh: "後桀黨與有譖光者，上輒怒曰：「大將軍忠臣，先帝所屬以輔朕身，敢有毀者坐之！", literal: "Later when Jie's faction had someone who slandered Guang, the emperor at once angrily said: \"The Grand General is a loyal minister, whom the late emperor entrusted to assist my person—whoever dares slander him shall be punished!", idiomatic: "Later when Jie's faction had someone who slandered Guang, the emperor at once angrily said, \"The Grand General is a loyal minister, whom the late emperor entrusted to assist my person—whoever dares slander him shall be punished!" },
  { zh: "」自是桀等不敢復言。", literal: "\" From this Jie and others did not dare speak again.", idiomatic: "\" From this Jie and others did not dare speak again." },
  { zh: ":李德裕論曰：人君之德，莫大於至明，明以照奸，則百邪不能蔽矣。", literal: ": Li Deyu's discourse says: Of a ruler's virtue none is greater than utmost clarity; clarity to illuminate treachery—then the hundred evils cannot screen it.", idiomatic: ": Li Deyu's discourse says: Of a ruler's virtue none is greater than utmost clarity; clarity to illuminate treachery—then the hundred evils cannot screen it." },
  { zh: "漢昭帝是也。", literal: "Emperor Zhao of Han was such.", idiomatic: "Emperor Zhao of Han was such." },
  { zh: "周成王有慚德矣；", literal: "King Cheng of Zhou had a virtue to be ashamed of;", idiomatic: "King Cheng of Zhou had a virtue to be ashamed of;" },
  { zh: "高祖、文、景俱不如也。", literal: "Gaozu, Wen, and Jing were all not as good.", idiomatic: "Gaozu, Wen, and Jing were all not as good." },
  { zh: "成王聞管、蔡流言，遂使周公狼跋而東。", literal: "King Cheng heard Guan and Cai's slanderous words and thereupon sent the Duke of Zhou off east in troubled haste.", idiomatic: "King Cheng heard Guan and Cai's slanderous words and thereupon sent the Duke of Zhou off east in troubled haste." },
  { zh: "漢高聞陳平去魏背楚，欲捨腹心臣。", literal: "Han Gaozu heard Chen Ping left Wei and turned against Chu and wished to abandon his trusted inner minister.", idiomatic: "Han Gaozu heard Chen Ping had left Wei and turned against Chu and wished to abandon his trusted inner minister." },
  { zh: "漢文惑季布使酒難近，罷歸股肱郡；", literal: "Emperor Wen of Han was confused by Ji Bu's wine-drinking and difficulty of approach, dismissed him and sent him back to a limb-and-trunk commandery;", idiomatic: "Emperor Wen of Han was confused by Ji Bu's wine-drinking and difficulty of approach, dismissed him and sent him back to a limb-and-trunk commandery;" },
  { zh: "疑賈生擅權紛亂，復疏賢士。", literal: "suspected Jia Yi of monopolizing power and stirring disorder, and again kept worthy scholars at a distance.", idiomatic: "suspected Jia Yi of monopolizing power and stirring disorder, and again kept worthy scholars at a distance." },
  { zh: "景帝信誅晁錯兵解，遂戮三公。", literal: "Emperor Jing believed the execution of Chao Cuo would dissolve the army and thereupon executed the Three Excellencies.", idiomatic: "Emperor Jing believed the execution of Chao Cuo would dissolve the army and thereupon executed the Three Excellencies." },
  { zh: "所謂「執狐疑之心，來讒賊之口」。", literal: "What is called \"holding a fox-suspicious heart, inviting the mouths of slanderous villains.\"", idiomatic: "What is called \"holding a fox-suspicious heart, inviting the mouths of slanderous villains.\"" },
  { zh: "使昭帝得伊、呂之佐，則成、康不足侔矣。", literal: "If Emperor Zhao had Yi and Lü as assistants, then Cheng and Kang would not be worth matching.", idiomatic: "If Emperor Zhao had Yi and Lü as assistants, then Cheng and Kang would not be worth matching." },
  { zh: "----6桀等謀令長公主置酒請光，伏兵格殺之，因廢帝，迎立燕王為天子。", literal: "----6 Jie and others plotted to have the Eldest Princess set out wine and invite Guang, with hidden troops strike and kill him, thereby depose the emperor, and welcome and establish the King of Yan as Son of Heaven.", idiomatic: "----6 Jie and others plotted to have the Eldest Princess set out wine and invite Guang, with hidden troops strike and kill him, thereby depose the emperor, and welcome and establish the King of Yan as Son of Heaven." },
  { zh: "旦置驛書往來相報，許立桀為王，外連郡國豪桀以千數。", literal: "Dan set up relay-post letters going back and forth reporting to each other, promised to establish Jie as king, and outward connected with powerful men of commanderies and states by the thousands.", idiomatic: "Dan set up relay-post letters going back and forth reporting to each other, promised to establish Jie as king, and outward connected with powerful men of commanderies and states by the thousands." },
  { zh: "旦以語相平，平曰：「大王前與劉澤結謀，事未成而發覺者，以劉澤素誇，好侵陵也。", literal: "Dan told Chancellor Ping; Ping said: \"Your Highness formerly with Liu Ze formed a plot; the affair did not succeed and was discovered—because Liu Ze was by nature boastful and fond of encroaching and bullying.", idiomatic: "Dan told Chancellor Ping; Ping said, \"Your Highness formerly with Liu Ze formed a plot; the affair did not succeed and was discovered—because Liu Ze was by nature boastful and fond of encroaching and bullying." },
  { zh: "平聞左將軍素輕易，車騎將軍少而驕，臣恐其如劉澤時不能成，又恐既成反大王也。", literal: "Ping has heard the Left General is by nature frivolous and easy, the Commandant of Cavalry and Chariots young and arrogant—your subject fears they will be like Liu Ze's time and not succeed, and also fears that if they succeed they will turn against Your Highness.", idiomatic: "Ping has heard the Left General is by nature frivolous and easy, the Commandant of Cavalry and Chariots young and arrogant—your subject fears they will be like Liu Ze's time and not succeed, and also fears that if they succeed they will turn against Your Highness." },
  { zh: "」旦曰：「前日一男子詣闕，自謂故太子，長安中民趣鄉之，正讙不可止。", literal: "\" Dan said: \"The other day a man came to the palace gate and called himself the former crown prince; the people of Chang'an rushed to go toward him—the clamor could not be stopped.", idiomatic: "\" Dan said, \"The other day a man came to the palace gate and called himself the former crown prince; the people of Chang'an rushed to go toward him—the clamor could not be stopped." },
  { zh: "大將軍恐，出兵陳之，以自備耳。", literal: "The Grand General was afraid, sent out troops and arrayed them—that was only to prepare himself.", idiomatic: "The Grand General was afraid, sent out troops and arrayed them—that was only to prepare himself." },
  { zh: "我，帝長子，天下所信，何憂見反！", literal: "I am the emperor's eldest son, trusted by all under Heaven—what worry of being turned against!", idiomatic: "I am the emperor's eldest son, trusted by all under Heaven—what worry of being turned against!" },
  { zh: "」後謂群臣：「蓋主報言，獨患大將軍與右將軍王莽。", literal: "\" Later he told the ministers: \"Princess Gaishan reports that she alone worries over the Grand General and Right General Wang Mang.", idiomatic: "\" Later he told the ministers, \"Princess Gaishan reports that she alone worries over the Grand General and Right General Wang Mang." },
  { zh: "今右將軍物故，丞相病，幸事必成，征不久。", literal: "Now the Right General is deceased, the Chancellor is ill—fortunately the affair is sure to succeed; the expedition will not be long.", idiomatic: "Now the Right General is deceased, the Chancellor is ill—fortunately the affair is sure to succeed; the expedition will not be long." },
  { zh: "」令群臣皆裝。", literal: "\" He ordered the ministers all to pack.", idiomatic: "\" He ordered the ministers all to pack." },
  { zh: "安又謀誘燕王至而誅之，因廢帝而立桀。", literal: "An again plotted to lure the King of Yan to come and execute him, thereby depose the emperor and establish Jie.", idiomatic: "An again plotted to lure the King of Yan to come and execute him, thereby depose the emperor and establish Jie." },
  { zh: "或曰：「當如皇后何？", literal: "Someone said: \"What about the empress?", idiomatic: "Someone said, \"What about the empress?" },
  { zh: "」安曰：「逐麋之狗，當顧菟邪！", literal: "\" An said: \"A dog chasing elk—should it look back at a rabbit!", idiomatic: "\" An said, \"A dog chasing elk—should it look back at a rabbit!" },
  { zh: "且用皇后為尊，一旦人主意有所移，雖欲為家人亦不可得。", literal: "Moreover, using the empress as honored—once the ruler's intent shifts, even if one wishes to be family one cannot obtain it.", idiomatic: "Moreover, using the empress as honored—once the ruler's intent shifts, even if one wishes to be family one cannot obtain it." },
  { zh: "此百世之一時也！", literal: "This is a once-in-a-hundred-generations moment!", idiomatic: "This is a once-in-a-hundred-generations moment!" },
  { zh: "」會蓋主舍人父稻田使者燕倉知其謀，以告大司農楊敞。", literal: "\" It happened Princess Gaishan's house retainer's father, Paddy-Field Envoy Yan Cang, knew their plot and reported it to Grand Minister of Agriculture Yang Chang.", idiomatic: "\" It happened Princess Gaishan's house retainer's father, Paddy-Field Envoy Yan Cang, knew their plot and reported it to Grand Minister of Agriculture Yang Chang." },
  { zh: "敞素謹，畏事，不敢言，乃移病臥，以告諫大夫杜延年；", literal: "Chang was by nature cautious, feared affairs, and did not dare speak; he then pleaded illness and lay abed, and told Remonstrance Grandee Du Yanian;", idiomatic: "Chang was by nature cautious, feared affairs, and did not dare speak; he then pleaded illness and lay abed, and told Remonstrance Grandee Du Yanian;" },
  { zh: "延年以聞。", literal: "Yanian reported it.", idiomatic: "Yanian reported it." },
  { zh: "九月，詔丞相部中二千石逐捕孫縱之及桀、安、弘羊、外人等，並宗族悉誅之；", literal: "In the ninth month, an edict ordered the Chancellor's department officials of two thousand bushels to pursue and capture Sun Zongzhi and Jie, An, Hongyang, Wairen, and others, and together with their clans all were executed;", idiomatic: "In the ninth month, an edict ordered the Chancellor's department officials of two thousand bushels to pursue and capture Sun Zongzhi and Jie, An, Hongyang, Wairen, and others, and together with their clans all were executed;" },
  { zh: "蓋主自殺。", literal: "Princess Gaishan killed herself.", idiomatic: "Princess Gaishan killed herself." },
  { zh: "燕王旦聞之，召相平曰：「事敗，遂發兵乎？", literal: "The King of Yan Dan heard it and summoned Chancellor Ping, saying: \"The affair has failed—shall we at once raise troops?", idiomatic: "The King of Yan Dan heard it and summoned Chancellor Ping, saying, \"The affair has failed—shall we at once raise troops?" },
  { zh: "」平曰：「左將軍已死，百姓皆知之，不可發也。", literal: "\" Ping said: \"The Left General is already dead; the common people all know it—it cannot be raised.", idiomatic: "\" Ping said, \"The Left General is already dead; the common people all know it—it cannot be raised." },
  { zh: "」王憂懣，置酒與群臣、妃妾別。", literal: "\" The king in worry and distress set out wine and took leave of ministers, consorts, and concubines.", idiomatic: "\" The king in worry and distress set out wine and took leave of ministers, consorts, and concubines." },
  { zh: "會天子以璽書讓旦，旦以綬自絞死，-{后}-、夫人隨旦自殺者二十餘人。", literal: "It happened the Son of Heaven with a seal-letter reproached Dan; Dan with his ribbon strangled himself—over twenty -{后}- and ladies who followed Dan in suicide.", idiomatic: "It happened the Son of Heaven with a seal-letter reproached Dan; Dan with his ribbon strangled himself—over twenty -{后}- and ladies who followed Dan in suicide." },
  { zh: "天子加恩，赦王太子建為庶人，賜量謚曰剌王。", literal: "The Son of Heaven added grace, pardoned the king's crown prince Jian as a commoner, and granted Liang the posthumous title Spur King.", idiomatic: "The Son of Heaven added grace, pardoned the king's crown prince Jian as a commoner, and granted Liang the posthumous title Spur King." },
  { zh: "皇后以年少，不與謀，亦霍光外孫，故得不廢。", literal: "The empress because she was young and had not joined the plot, and was also Huo Guang's maternal grandson's daughter, therefore was not deposed.", idiomatic: "The empress because she was young and had not joined the plot, and was also Huo Guang's maternal grandson's daughter, therefore was not deposed." },
  { zh: "----7庚午，右扶風王訢為御史大夫。", literal: "----7 On gengwu, Wang Xin of Right Fufeng was made Grand Counsellor.", idiomatic: "----7 On gengwu, Wang Xin of Right Fufeng was appointed Grand Counsellor." },
  { zh: "----8冬，十月，封杜延年為建平侯；", literal: "----8 In winter, the tenth month, Du Yanian was enfeoffed as Marquis of Jianping;", idiomatic: "----8 In winter, the tenth month, Du Yanian was enfeoffed as Marquis of Jianping;" },
  { zh: "燕倉為宜城侯；", literal: "Yan Cang as Marquis of Yicheng;", idiomatic: "Yan Cang as Marquis of Yicheng;" },
  { zh: "故丞相征事任宮捕得桀，為弋陽侯；", literal: "former Chancellor's investigating officer Ren Gong captured Jie and was made Marquis of Yiyang;", idiomatic: "former Chancellor's investigating officer Ren Gong captured Jie and was made Marquis of Yiyang;" },
  { zh: "丞相少史王山壽誘安入府，為商利侯。", literal: "Chancellor's junior clerk Wang Shanshou lured An into the office and was made Marquis of Shangli.", idiomatic: "Chancellor's junior clerk Wang Shanshou lured An into the office and was made Marquis of Shangli." },
  { zh: "久之，文學濟陰魏相對策，以為：「日者燕王為無道，韓義出身強諫，為王所殺。", literal: "After a long time, Erudite Wei Xiang of Jiyin in his policy response thought: \"Recently the King of Yan was without the Way; Han Yi from his person strongly remonstrated and was killed by the king.", idiomatic: "After a long time, Erudite Wei Xiang of Jiyin in his policy response thought, \"Recently the King of Yan was without the Way; Han Yi from his person strongly remonstrated and was killed by the king." },
  { zh: "義無比干之親而蹈比干之節，宜顯賞其子以示天下，明為人臣之義。", literal: "Yi had not Bi Gan's kinship yet trod Bi Gan's integrity—his son should be prominently rewarded to show all under Heaven and clarify the righteousness of being a minister.", idiomatic: "Yi had not Bi Gan's kinship yet trod Bi Gan's integrity—his son should be prominently rewarded to show all under Heaven and clarify the righteousness of being a minister." },
  { zh: "」乃擢義子延壽為諫大夫。", literal: "\" Thereupon Yi's son Yanshou was promoted to Remonstrance Grandee.", idiomatic: "\" Thereupon Yi's son Yanshou was promoted to Remonstrance Grandee." },
  { zh: "----9大將軍光以朝無舊臣，光祿勳張安世自先帝時為尚書令，志行純篤，乃白用安世為右將軍兼光祿勳以自副焉。", literal: "----9 The Grand General Guang, because the court had no old ministers, and Palace Chamberlain Zhang Anshi from the late emperor's time had been Master of Writing, his will and conduct pure and sincere, thereupon reported to employ Anshi as Right General concurrently Palace Chamberlain to assist himself.", idiomatic: "----9 The Grand General Guang, because the court had no old ministers, and Palace Chamberlain Zhang Anshi from the late emperor's time had been Master of Writing, his will and conduct pure and sincere, thereupon reported to employ Anshi as Right General concurrently Palace Chamberlain to assist himself." },
  { zh: "安世，故御史大夫湯之子也。", literal: "Anshi was the son of former Grand Counsellor Tang.", idiomatic: "Anshi was the son of former Grand Counsellor Tang." },
  { zh: "光又以杜延年有忠節，擢為太僕、右曹、給事中。", literal: "Guang also because Du Yanian had loyal integrity promoted him to Grand Coachman, Right Bureau, and Palace Attendant.", idiomatic: "Guang also because Du Yanian had loyal integrity promoted him to Grand Coachman, Right Bureau, and Palace Attendant." },
  { zh: "光持刑罰嚴，延年常輔之以寬。", literal: "Guang held punishments strict; Yanian often assisted him with leniency.", idiomatic: "Guang held punishments strict; Yanian often assisted him with leniency." },
  { zh: "吏民上書言便宜，輒下延年平處復奏。", literal: "When officials and people memorialized on convenient measures, he at once sent them down to Yanian to balance and settle and then memorialize again.", idiomatic: "When officials and people memorialized on convenient measures, he at once sent them down to Yanian to balance and settle and then memorialize again." },
  { zh: "言可官試者，至為縣令；", literal: "Those whose words could be tried in office reached as far as county magistrate;", idiomatic: "Those whose words could be tried in office reached as far as county magistrate;" },
  { zh: "或丞相、御史除用，滿歲，以狀聞；", literal: "or the Chancellor and Grand Counsellor appointed and employed them; when a full year was complete, they reported the circumstances;", idiomatic: "or the Chancellor and Grand Counsellor appointed and employed them; when a full year was complete, they reported the circumstances;" },
  { zh: "或抵其罪法。", literal: "or they were charged according to the penal law.", idiomatic: "or they were charged according to the penal law." },
  { zh: "----10是歲匈奴發左、右部二萬騎為四隊，並入邊為寇。", literal: "----10 This year the Xiongnu sent twenty thousand horsemen of the left and right divisions in four columns, together entering the border as raiders.", idiomatic: "----10 This year the Xiongnu sent twenty thousand horsemen of the left and right divisions in four columns, together entering the border as raiders." },
  { zh: "漢兵追之，斬首、獲虜九千人，生得甌脫王；", literal: "Han troops pursued them, beheaded and captured nine thousand; they took alive King Ouduo;", idiomatic: "Han troops pursued them, beheaded and captured nine thousand; they took alive King Ouduo;" },
  { zh: "漢無所失亡。", literal: "Han had no losses.", idiomatic: "Han had no losses." },
  { zh: "匈奴見甌脫王在漢，恐，以為道擊之，即西北遠去，不敢南逐水草；", literal: "The Xiongnu saw King Ouduo was in Han and were afraid, thinking Han would strike along the road; they at once went far northwest and did not dare south to pursue water and pasture;", idiomatic: "The Xiongnu saw King Ouduo was in Han and were afraid, thinking Han would strike along the road; they at once went far northwest and did not dare south to pursue water and pasture;" },
  { zh: "發人民屯甌脫。", literal: "they sent the people to garrison Ouduo.", idiomatic: "they sent the people to garrison Ouduo." },
  { zh: "1夏，四月，上自建章宮徙未央宮。", literal: "1 In summer, the fourth month, the emperor moved from Jianzhang Palace to Weiyang Palace.", idiomatic: "1 In summer, the fourth month, the emperor moved from Jianzhang Palace to Weiyang Palace." },
  { zh: "----2六月，赦天下。", literal: "----2 In the sixth month, amnesty for all under Heaven.", idiomatic: "----2 In the sixth month, there was an amnesty for all under Heaven." },
  { zh: "----3是歲，匈奴復遣九千騎屯受降城以備漢，北橋余吾水，令可度，以備奔走；", literal: "----3 This year the Xiongnu again sent nine thousand horsemen to garrison Shoujiang city to prepare against Han, bridged north across Yuwu River so it could be crossed, to prepare for flight;", idiomatic: "----3 This year the Xiongnu again sent nine thousand horsemen to garrison Shoujiang city to prepare against Han, bridged north across Yuwu River so it could be crossed, to prepare for flight;" },
  { zh: "欲求和親，而恐漢不聽，故不肯先言，常使左右風漢使者。", literal: "they wished to seek heqin peace marriage but feared Han would not listen, therefore would not speak first, and often had those close to them hint to Han envoys.", idiomatic: "they wished to seek heqin peace marriage but feared Han would not listen, therefore would not speak first, and often had those close to them hint to Han envoys." },
  { zh: "然其侵盜益希，遇漢使愈厚，欲以漸致和親。", literal: "Yet their raids and plunder grew ever rarer, and meeting Han envoys they were ever more generous—wishing by degrees to bring about heqin.", idiomatic: "Yet their raids and plunder grew ever rarer, and meeting Han envoys they were ever more generous—wishing by degrees to bring about heqin." },
  { zh: "漢亦羈縻之。", literal: "Han also held them with bridles and reins.", idiomatic: "Han also held them with bridles and reins." },
  { zh: "1春，正月，泰山有大石自起立；", literal: "1 In spring, the first month, on Mount Tai a great stone by itself stood up;", idiomatic: "1 In spring, the first month, on Mount Tai a great stone by itself stood up;" },
  { zh: "上林有柳樹枯僵自起生；", literal: "in Shanglin a willow tree, dead and stiff, by itself rose and lived;", idiomatic: "in Shanglin a willow tree, dead and stiff, by itself rose and lived;" },
  { zh: "有蟲食其葉成文，曰「公孫病已立」。", literal: "insects ate its leaves forming characters saying \"Gongsun Bingyi established.\"", idiomatic: "insects ate its leaves forming characters saying \"Gongsun Bingyi established.\"" },
  { zh: "符節令魯國眭弘上書，言：「大石自立，僵柳復起，當有匹庶為天子者。", literal: "Staff-and-tally Director Sui Hong of Lu submitted a memorial, saying: \"The great stone stood by itself, the stiff willow revived—there ought to be a commoner who becomes Son of Heaven.", idiomatic: "Staff-and-tally Director Sui Hong of Lu submitted a memorial, saying, \"The great stone stood by itself, the stiff willow revived—there ought to be a commoner who becomes Son of Heaven." },
  { zh: "枯樹復生，故廢之家公孫氏當復興乎？", literal: "A dead tree revives—perhaps the Gongsun clan of the abolished house should revive?", idiomatic: "A dead tree revives—perhaps the Gongsun clan of the abolished house should revive?" },
  { zh: "漢家承堯之後，有傳國之運，當求賢人禪帝位，退自封百里，以順天命。", literal: "The House of Han succeeds after Yao and has the fortune to transmit the state—one should seek a worthy man and yield the imperial throne, retire and enfeoff oneself with a hundred li, to accord with Heaven's mandate.", idiomatic: "The House of Han succeeds after Yao and has the fortune to transmit the state—one should seek a worthy man and yield the imperial throne, retire and enfeoff oneself with a hundred li, to accord with Heaven's mandate." },
  { zh: "」弘坐設妖言惑眾伏誅。", literal: "\" Hong was punished for setting up freakish words to delude the masses and was executed.", idiomatic: "\" Hong was punished for setting up freakish words to delude the masses and was executed." },
  { zh: "----2匈奴單于使犁汙王窺邊，言酒泉、張掖兵益弱，出兵試擊，冀可復得其地。", literal: "----2 The Xiongnu Chanyu sent King Liwu to spy on the border, saying Jiuquan and Zhangye troops were growing weaker—send troops to try striking, hoping to recover their territory.", idiomatic: "----2 The Xiongnu Chanyu sent King Liwu to spy on the border, saying Jiuquan and Zhangye troops were growing weaker—send troops to try striking, hoping to recover their territory." },
  { zh: "時漢先得降者，聞其計，天子詔邊警備。", literal: "At this time Han first obtained surrenderers and heard their plan; the Son of Heaven edicted the border to warn and prepare.", idiomatic: "At this time Han first obtained surrenderers and heard their plan; the Son of Heaven edicted the border to warn and prepare." },
  { zh: "後無幾，右賢王、犁汙王四千騎分三隊，入日勒、屋蘭、番和。", literal: "Not long after, the Wise King of the Right and King Liwu with four thousand horsemen divided into three columns and entered Rile, Wulan, and Fanhe.", idiomatic: "Not long after, the Wise King of the Right and King Liwu with four thousand horsemen divided into three columns and entered Rile, Wulan, and Fanhe." },
  { zh: "張掖太守、屬國都尉發兵擊，大破之，得脫者數百人。", literal: "The Administrator of Zhangye and Commandant of the Dependent State raised troops and struck, greatly defeated them; those who escaped were several hundred.", idiomatic: "The Administrator of Zhangye and Commandant of the Dependent State raised troops and struck, greatly defeated them; those who escaped were several hundred." },
  { zh: "屬國義渠王射殺犁汙王，賜黃金二百斤，馬二百匹，因封為犁汙王。", literal: "King Yiqu of the Dependent State shot and killed King Liwu; he was granted two hundred jin of gold and two hundred horses, and thereby enfeoffed as King Liwu.", idiomatic: "King Yiqu of the Dependent State shot and killed King Liwu; he was granted two hundred jin of gold and two hundred horses, and thereby enfeoffed as King Liwu." },
  { zh: "自是後，匈奴不敢入張掖。", literal: "From this afterward the Xiongnu did not dare enter Zhangye.", idiomatic: "From this afterward the Xiongnu did not dare enter Zhangye." },
  { zh: "----3燕、蓋之亂，桑弘羊子遷亡，過父故吏侯史吳，後遷捕得，伏法。", literal: "----3 In the Yan and Gaishan disorder, Sang Hongyang's son Qian fled, passed his father's old clerk Marquis-History Wu; later Qian was captured and punished by law.", idiomatic: "----3 In the Yan and Gaishan disorder, Sang Hongyang's son Qian fled, passed his father's old clerk Marquis-History Wu; later Qian was captured and punished by law." },
  { zh: "會赦，侯史吳自出繫獄。", literal: "An amnesty occurred; Marquis-History Wu of himself came out of imprisonment.", idiomatic: "An amnesty occurred; Marquis-History Wu of himself came out of imprisonment." },
  { zh: "廷尉王平、少府徐仁雜治反事，皆以為「桑遷坐父謀反而侯史吳臧之，非匿反者，乃匿為隨者也」，即以赦令除吳罪。", literal: "Director of Justice Wang Ping and Privy Treasurer Xu Ren jointly tried the rebellion affair; all thought \"Qian sat under his father's plotting rebellion and Marquis-History Wu hid him—not hiding a rebel but hiding a follower\"—and thereby by the amnesty edict removed Wu's crime.", idiomatic: "Director of Justice Wang Ping and Privy Treasurer Xu Ren jointly tried the rebellion affair; all thought \"Qian sat under his father's plotting rebellion and Marquis-History Wu hid him—not hiding a rebel but hiding a follower\"—and thereby by the amnesty edict removed Wu's crime." },
  { zh: "後侍御史治實，以「桑遷通經術，知父謀反而不諫爭，與反者身無異。", literal: "Later the attendant censor investigated the facts and held that \"Qian mastered the classics, knew his father plotted rebellion yet did not remonstrate and contend—in person no different from rebels.", idiomatic: "Later the attendant censor investigated the facts and held that \"Qian mastered the classics, knew his father plotted rebellion yet did not remonstrate and contend—in person no different from rebels." },
  { zh: "侯史吳故三百石吏，首匿遷，不與庶人匿隨從者等，吳不得赦。", literal: "Marquis-History Wu was formerly an official of three hundred bushels who first hid Qian—not equal to commoners hiding followers—Wu could not receive amnesty.", idiomatic: "Marquis-History Wu was formerly an official of three hundred bushels who first hid Qian—not equal to commoners hiding followers—Wu could not receive amnesty." },
  { zh: "」奏請覆治，劾廷尉、少府縱反者。", literal: "\" The memorial requested renewed trial and impeached the Director of Justice and Privy Treasurer for indulging rebels.", idiomatic: "\" The memorial requested renewed trial and impeached the Director of Justice and Privy Treasurer for indulging rebels." },
  { zh: "少府徐仁，即丞相車千秋女婿也，故千秋數為侯史吳言；", literal: "Privy Treasurer Xu Ren was Chancellor Che Qianqiu's son-in-law; therefore Qianqiu repeatedly spoke for Marquis-History Wu;", idiomatic: "Privy Treasurer Xu Ren was Chancellor Che Qianqiu's son-in-law; therefore Qianqiu repeatedly spoke for Marquis-History Wu;" },
  { zh: "恐大將軍光不聽，千秋即召中二千石、博士會公車門，議問吳法。", literal: "fearing Grand General Guang would not listen, Qianqiu then summoned officials of the middle two thousand bushels and erudites to meet at the Public Carriage Gate and discuss and question Wu's law.", idiomatic: "fearing Grand General Guang would not listen, Qianqiu then summoned officials of the middle two thousand bushels and erudites to meet at the Public Carriage Gate and discuss and question Wu's law." },
  { zh: "議者知大將軍指，皆執吳為不道。", literal: "The discussants knew the Grand General's intent and all held Wu as lawless.", idiomatic: "The discussants knew the Grand General's intent and all held Wu as lawless." },
  { zh: "明日，千秋封上眾議。", literal: "The next day Qianqiu sealed and sent up the collective discussion.", idiomatic: "The next day Qianqiu sealed and sent up the collective discussion." },
  { zh: "光於是以千秋擅召中二千石以下，外內異言，遂下廷尉平、少府仁獄。", literal: "Guang thereupon because Qianqiu on his own authority summoned middle two thousand bushels and below, with outer and inner differing words, sent down Director of Justice Ping and Privy Treasurer Ren to prison.", idiomatic: "Guang thereupon because Qianqiu on his own authority summoned middle two thousand bushels and below, with outer and inner differing words, sent down Director of Justice Ping and Privy Treasurer Ren to prison." },
  { zh: "朝廷皆恐丞相坐之。", literal: "The court all feared the Chancellor would be implicated.", idiomatic: "The court all feared the Chancellor would be implicated." },
  { zh: "太僕杜延年奏記光曰：「吏縱罪人，有常法。", literal: "Grand Coachman Du Yanian submitted a note to Guang, saying: \"Officials who indulge criminals have a regular law.", idiomatic: "Grand Coachman Du Yanian submitted a note to Guang, saying, \"Officials who indulge criminals have a regular law." },
  { zh: "今更詆吳為不道，恐於法深。", literal: "Now again denouncing Wu as lawless—your subject fears it is deep in the law.", idiomatic: "Now again denouncing Wu as lawless—I fear it is deep in the law." },
  { zh: "又，丞相素無所守持而為好言於下，盡其素行也。", literal: "Moreover, the Chancellor by nature has nothing he holds to and speaks kindly to those below—that is fully his usual conduct.", idiomatic: "Moreover, the Chancellor by nature has nothing he holds to and speaks kindly to those below—that is fully his usual conduct." },
  { zh: "至擅召中二千石，甚無狀。", literal: "As for on his own authority summoning middle two thousand bushels—that is very lawless.", idiomatic: "As for on his own authority summoning middle two thousand bushels—that is very lawless." },
  { zh: "延年愚以為丞相久故及先帝用事，非有大故，不可棄也。", literal: "Yanian foolishly thinks the Chancellor is long in office and served the late emperor—without a great cause he cannot be abandoned.", idiomatic: "Yanian foolishly thinks the Chancellor is long in office and served the late emperor—without a great cause he cannot be abandoned." },
  { zh: "間者民頗言獄深，吏為峻詆；", literal: "Of late the people have often said the prisons are deep and harsh, and the officials make severe slander;", idiomatic: "Of late the people have often said the prisons are harsh and officials make severe accusations;" },
  { zh: "今丞相所議，又獄事也，如是以及丞相，恐不合眾心，群下讙嘩，庶人私議，流言四布。", literal: "now what the Chancellor discusses is again a prison matter; if in this fashion it extends to the Chancellor, I fear it will not accord with the hearts of the multitude—the ranks below will clamor, commoners will privately discuss, and floating slander will spread in all directions.", idiomatic: "now what the Chancellor discusses is again a prison matter; if it extends to the Chancellor in this fashion, I fear it will not accord with popular sentiment—the officials will clamor, commoners will gossip privately, and rumors will spread everywhere." },
  { zh: "延年竊重將軍失此名於天下也。", literal: "Yannian privately fears the General will lose this reputation under Heaven.", idiomatic: "Yannian privately fears the General will lose this reputation throughout the realm." },
  { zh: "」光以廷尉、少府弄法輕重，卒下之獄。", literal: "\" Guang, because the Director of Justice and the Minister Steward manipulated the law regarding severity, finally sent them to prison.", idiomatic: "\" Guang, because the Director of Justice and the Minister Steward had manipulated the law regarding severity, finally sent them to prison." },
  { zh: "夏，四月，仁自殺，平與左馮翊賈勝胡皆要斬。", literal: "In summer, the fourth month, Ren committed suicide; Ping and the Left Governor of Anding Jia Shenghu were all executed by waist chop.", idiomatic: "In summer, the fourth month, Ren committed suicide; Ping and Left Governor of Anding Jia Shenghu were all executed by waist chop." },
  { zh: "而不以及丞相，終與相竟。", literal: "Yet he did not extend it to the Chancellor; in the end he still contended with the Chancellor to the finish.", idiomatic: "Yet he did not extend the matter to the Chancellor; in the end he still came to a final contest with the Chancellor." },
  { zh: "延年論議持平，合和朝廷，皆此類也。", literal: "Yannian's discussions and judgments were even-handed and harmonized the court—all were of this sort.", idiomatic: "Yannian's discussions were even-handed and harmonized the court—all were of this sort." },
  { zh: "----4冬，遼東烏桓反。", literal: "----4 In winter, the Wuhuan of Liaodong rebelled.", idiomatic: "----4 In winter, the Wuhuan of Liaodong rebelled." },
  { zh: "初，冒頓破東胡，東胡餘眾散保烏桓及鮮卑山為二族，世役屬匈奴。", literal: "Initially Modun broke the Eastern Hu; the Eastern Hu's remaining masses scattered and took refuge on Wuhuan and Xianbei mountains as two peoples, generation after generation subject to corvée and allegiance to the Xiongnu.", idiomatic: "Initially Modun defeated the Eastern Hu; the Eastern Hu remnant peoples scattered and took refuge on the Wuhuan and Xianbei mountains as two peoples, for generations subject to corvée and allegiance to the Xiongnu." },
  { zh: "武帝出破匈奴左地，因徙烏桓於上谷、漁陽、右北平、遼東塞外，為漢偵察匈奴動靜。", literal: "Emperor Wu went out and broke the Xiongnu's left territory; he thereupon moved the Wuhuan to beyond the passes of Shanggu, Yuyang, Right Beiping, and Liaodong, to spy on the Xiongnu's movements for Han.", idiomatic: "When Emperor Wu campaigned and broke the Xiongnu's left territory, he moved the Wuhuan beyond the passes of Shanggu, Yuyang, Right Beiping, and Liaodong to spy on Xiongnu movements for Han." },
  { zh: "置護烏桓校尉監領之，使不得與匈奴交通。", literal: "He set a Colonel Protecting the Wuhuan to oversee and lead them, so they could not communicate with the Xiongnu.", idiomatic: "He appointed a Colonel Protecting the Wuhuan to oversee them, so they could not communicate with the Xiongnu." },
  { zh: "至是，部眾漸強，遂反。", literal: "At this time their tribal masses gradually grew strong, and they thereupon rebelled.", idiomatic: "By this time their tribes had gradually grown strong, and they rebelled." },
  { zh: "先是，匈奴三千餘騎入五原，殺略數千人；", literal: "Earlier, more than three thousand Xiongnu horsemen entered Wuyuan and killed and plundered several thousand people;", idiomatic: "Earlier, more than three thousand Xiongnu horsemen entered Wuyuan and killed and plundered several thousand people;" },
  { zh: "後數萬騎南旁塞獵，行攻塞外亭障，略取吏民去。", literal: "later tens of thousands of horsemen came south along the border passes to hunt, marched attacking border towers and barriers beyond the passes, and plundered officials and people away.", idiomatic: "later tens of thousands of horsemen came south along the border passes to hunt, attacked border towers and barriers beyond the passes, and carried off officials and civilians." },
  { zh: "是時漢邊郡烽火候望精明，匈奴為邊寇者少利，希復犯塞。", literal: "At this time Han's border commanderies' beacon fires and watch posts were keen and clear; when the Xiongnu raided the border they gained little profit and rarely again violated the passes.", idiomatic: "At this time Han border commanderies' beacon fires and watch posts were keen; when the Xiongnu raided the border they gained little and rarely again violated the passes." },
  { zh: "漢復得匈奴降者，言烏桓嘗發先單于塚，匈奴怨之，方發二萬騎擊烏桓。", literal: "Han again obtained Xiongnu surrenderers who said the Wuhuan had once opened the former chanyu's tombs; the Xiongnu resented this and were just then sending twenty thousand horsemen to attack the Wuhuan.", idiomatic: "Han again obtained Xiongnu surrenderers who said the Wuhuan had once desecrated the former chanyu's tombs; the Xiongnu resented this and were about to send twenty thousand horsemen to attack the Wuhuan." },
  { zh: "霍光欲發兵邀擊之，以問護軍都尉趙充國，充國以為：「烏桓間數犯塞，今匈奴擊之，於漢便。", literal: "Huo Guang wished to dispatch troops to intercept and strike them; he asked Colonel Director of Retainers Zhao Chongguo. Chongguo thought: \"The Wuhuan have repeatedly violated the passes of late; now the Xiongnu are attacking them—this is convenient for Han.", idiomatic: "Huo Guang wished to dispatch troops to intercept them and asked Colonel Director of Retainers Zhao Chongguo. Chongguo thought, \"The Wuhuan have repeatedly violated the passes of late; now the Xiongnu are attacking them—this is convenient for Han." },
  { zh: "又匈奴希寇盜，北邊幸無事，蠻夷自相攻擊而發兵要之，招寇生事，非計也。", literal: "Moreover the Xiongnu rarely raid and plunder; the northern border is fortunately without affairs—if barbarians attack one another and we dispatch troops to intercept them, we invite barbarians and create trouble; this is not a plan.", idiomatic: "Moreover the Xiongnu rarely raid; the northern border is fortunately quiet—if barbarians attack one another and we dispatch troops to intercept them, we invite trouble; this is not sound policy." },
  { zh: "」光更問中郎將范明友，明友言可擊，於是拜明友為度遼將軍，將二萬騎出遼東。", literal: "\" Guang again asked Palace Gentleman Fan Mingyou; Mingyou said they could be struck. Thereupon he appointed Mingyou General Crossing the Liao, leading twenty thousand horsemen out from Liaodong.", idiomatic: "\" Guang again asked Palace Gentleman Fan Mingyou; Mingyou said they could be attacked. Thereupon he appointed Mingyou General Crossing the Liao, leading twenty thousand horsemen out from Liaodong." },
  { zh: "匈奴聞漢兵至，引去。", literal: "The Xiongnu heard Han troops had arrived and withdrew.", idiomatic: "The Xiongnu heard Han troops had arrived and withdrew." },
  { zh: "初，光誡明友：「兵不空出；", literal: "Initially Guang admonished Mingyou: \"Troops must not go out empty-handed;", idiomatic: "Initially Guang admonished Mingyou, \"Troops must not go out empty-handed;" },
  { zh: "即後匈奴，遂擊烏桓。", literal: "immediately follow the Xiongnu, then strike the Wuhuan.", idiomatic: "immediately follow the Xiongnu, then strike the Wuhuan." },
  { zh: "」烏桓時新中匈奴兵，明友既後匈奴，因乘烏桓敝，擊之，斬首六千餘級，獲三王首。", literal: "\" The Wuhuan had just then been struck by Xiongnu troops; Mingyou, having followed the Xiongnu, thereupon took advantage of the Wuhuan's exhaustion, struck them, and cut off more than six thousand heads, obtaining the heads of three kings.", idiomatic: "\" The Wuhuan had just been struck by Xiongnu troops; Mingyou, having followed the Xiongnu, took advantage of the Wuhuan's exhaustion, attacked them, cut off more than six thousand heads, and obtained the heads of three kings." },
  { zh: "匈奴由是恐，不能復出兵。", literal: "The Xiongnu from this were fearful and could not again dispatch troops.", idiomatic: "The Xiongnu were thereby fearful and could not again dispatch troops." },
  { zh: "1春，正月，丁亥，帝加元服。", literal: "1 In spring, the first month, on dinghai, the emperor performed the capping ceremony.", idiomatic: "1 In spring, the first month, on dinghai, the emperor performed the capping ceremony." },
  { zh: "----2甲戌，富民定侯田千秋薨。", literal: "----2 On jiaxu, Marquis Ding of Enriching the People Tian Qianqiu died.", idiomatic: "----2 On jiaxu, Marquis Ding of Enriching the People Tian Qianqiu died." },
  { zh: "時政事壹決大將軍光；", literal: "At this time all government affairs were decided solely by the Grand General Guang;", idiomatic: "At this time all government affairs were decided solely by Grand General Guang;" },
  { zh: "千秋居丞相位，謹厚自守而已。", literal: "Qianqiu occupied the chancellor's post and was merely careful, generous, and self-restrained.", idiomatic: "Qianqiu held the chancellorship and was merely careful, generous, and self-restrained." },
  { zh: "----3夏，五月，丁丑，孝文廟正殿火。", literal: "----3 In summer, the fifth month, on dingchou, the main hall of Emperor Wen's temple caught fire.", idiomatic: "----3 In summer, the fifth month, on dingchou, the main hall of Emperor Wen's temple caught fire." },
  { zh: "上及群臣皆素服，發中二千石將五校作治，六日，成。", literal: "The emperor and the ministers all wore plain mourning dress; he dispatched two-thousand-bushel officials to lead the Five Commandants in construction and repair—in six days it was completed.", idiomatic: "The emperor and ministers all wore plain mourning dress; he dispatched two-thousand-bushel officials to lead the Five Commandants in repairs—in six days it was completed." },
  { zh: "太常及廟令丞、郎、吏，皆劾大不敬；", literal: "The Grand Minister of Ceremonies and the temple directors, assistants, gentlemen, and clerks were all impeached for great irreverence;", idiomatic: "The Grand Minister of Ceremonies and the temple directors, assistants, gentlemen, and clerks were all impeached for great irreverence;" },
  { zh: "會赦，太常轑陽侯德免為庶人。", literal: "it happened there was an amnesty; the Grand Minister Marquis Liaoyang De was demoted to commoner.", idiomatic: "there was an amnesty; Grand Minister Marquis Liaoyang De was demoted to commoner status." },
  { zh: "----4六月，赦天下。", literal: "----4 In the sixth month, an amnesty for all under Heaven.", idiomatic: "----4 In the sixth month, an amnesty for all under Heaven." },
  { zh: "----5初，杅冞遣太子賴丹為質於龜茲；", literal: "----5 Initially Chijmi sent the heir Lai Dan as hostage to Kucha;", idiomatic: "----5 Initially Chijmi sent the heir Lai Dan as hostage to Kucha;" },
  { zh: "貳師擊大宛還，將賴丹入至京師。", literal: "the General of the Ershi, returning from attacking Dayuan, brought Lai Dan in to the capital.", idiomatic: "the General of the Ershi, returning from attacking Dayuan, brought Lai Dan to the capital." },
  { zh: "霍光用桑弘羊前議，以賴丹為校尉，將軍田輪台。", literal: "Huo Guang used Sang Hongyang's former proposal, making Lai Dan a colonel to lead troops farming at Luntai.", idiomatic: "Huo Guang followed Sang Hongyang's former proposal, making Lai Dan a colonel to lead troops farming at Luntai." },
  { zh: "龜茲貴人姑翼謂其王曰：「賴丹本臣屬吾國，今佩漢印綬來，迫吾國而田，必為害。", literal: "Kucha's noble Gu Yi said to its king: \"Lai Dan was originally a subject belonging to our state; now wearing Han seals and cords he has come, pressing upon our state to farm—he will surely be harmful.", idiomatic: "Kucha's noble Gu Yi said to its king, \"Lai Dan was originally a subject of our state; now wearing Han seals and cords he has come to press upon our state with farming—he will surely bring harm." },
  { zh: "」王即殺賴丹而上書謝漢。", literal: "\" The king immediately killed Lai Dan and memorialized apologizing to Han.", idiomatic: "\" The king immediately killed Lai Dan and memorialized apologizing to Han." },
  { zh: "樓蘭王死，匈奴先聞之，遣其質子安歸歸，得立為王。", literal: "The king of Loulan died; the Xiongnu heard of it first and sent their hostage An Guigui back; he obtained installation as king.", idiomatic: "The king of Loulan died; the Xiongnu heard first and sent their hostage An Guigui back; he was installed as king." },
  { zh: "漢遣使詔新王令入朝，王辭不至。", literal: "Han dispatched an envoy to instruct the new king to enter court; the king declined and did not come.", idiomatic: "Han dispatched an envoy ordering the new king to attend court; the king declined and did not come." },
  { zh: "樓蘭國最在東垂，近漢，當白龍堆，乏水草，常主發導，負水擔糧，送迎漢使；", literal: "Loulan's state was farthest on the eastern frontier, near Han, facing the White Dragon Mound; lacking water and grass, it constantly took the lead in guiding, carrying water and shouldering grain to receive and send off Han envoys;", idiomatic: "Loulan lay farthest on the eastern frontier, near Han, facing the White Dragon Mound; lacking water and grass, it constantly took the lead in guiding, carrying water and grain to receive and send off Han envoys;" },
  { zh: "又數為官吏卒所寇，懲艾，不便與漢通。", literal: "moreover it was repeatedly raided by officials and soldiers and disciplined—unwilling to communicate with Han.", idiomatic: "moreover it was repeatedly harassed by officials and soldiers and disciplined, and found communication with Han inconvenient." },
  { zh: "後復為匈奴反間，數遮殺漢使。", literal: "Later it again became the target of Xiongnu subversion and repeatedly intercepted and killed Han envoys.", idiomatic: "Later, through Xiongnu subversion, it repeatedly intercepted and killed Han envoys." },
  { zh: "其弟尉屠耆降漢，具言狀。", literal: "His younger brother Weituqi surrendered to Han and fully stated the circumstances.", idiomatic: "His younger brother Weituqi surrendered to Han and fully reported the circumstances." },
  { zh: "駿馬監北地傅介子使大宛，詔因令責樓蘭、龜茲。", literal: "Stud-Horse Supervisor Fu Jiezi of Beidi was sent to Dayuan; an edict thereby ordered him to reprove Loulan and Kucha.", idiomatic: "Stud-Horse Supervisor Fu Jiezi of Beidi was sent to Dayuan; an edict also ordered him to reprove Loulan and Kucha." },
  { zh: "介子至樓蘭、龜茲，責其王，皆謝服。", literal: "Jiezi reached Loulan and Kucha, reproved their kings, and both apologized and submitted.", idiomatic: "Jiezi reached Loulan and Kucha, reproved their kings, and both apologized and submitted." },
  { zh: "介子從大宛還，到龜茲，會匈奴使從烏孫還，在龜茲，介子因率其吏士共誅斬匈奴使者。", literal: "Jiezi returned from Dayuan, reached Kucha, and happened upon a Xiongnu envoy returning from Wusun who was in Kucha; Jiezi thereupon led his officials and soldiers together to execute and behead the Xiongnu envoy.", idiomatic: "Jiezi returned from Dayuan and reached Kucha; a Xiongnu envoy returning from Wusun was there; Jiezi led his officials and soldiers to execute the Xiongnu envoy." },
  { zh: "還，奏事，詔拜介子為中郎，遷平樂監。", literal: "Returning, he reported the affair; an edict appointed Jiezi as Palace Attendant and transferred him to Supervisor of Pingle.", idiomatic: "On his return he reported; an edict appointed Jiezi Palace Attendant and transferred him to Supervisor of Pingle." },
  { zh: "介子謂大將軍霍光曰：「樓蘭、龜茲數反覆，而不誅，無所懲艾。", literal: "Jiezi said to Grand General Huo Guang: \"Loulan and Kucha have repeatedly turned back and forth, yet if they are not executed there is no discipline.", idiomatic: "Jiezi said to Grand General Huo Guang, \"Loulan and Kucha have repeatedly turned traitor, yet if they are not punished there is no discipline." },
  { zh: "介子過龜茲時，其王近就人，易得也；", literal: "When Jiezi passed through Kucha, its king's attendants close at hand were near—he would be easy to obtain;", idiomatic: "When Jiezi passed through Kucha, the king's attendants were close at hand—he would be easy to reach;" },
  { zh: "願往刺之，以威示諸國。", literal: "your servant wishes to go and assassinate him, to display authority to the various states.", idiomatic: "your servant wishes to go assassinate him, to display authority to the various states." },
  { zh: "」大將軍曰：「龜茲道遠，且驗之於樓蘭。", literal: "\" The Grand General said: \"Kucha is far; first test it on Loulan.", idiomatic: "\" The Grand General said, \"Kucha is far; first test it on Loulan." },
  { zh: "」於是白遣之。", literal: "\" Thereupon he reported and dispatched him.", idiomatic: "\" Thereupon he reported to the throne and dispatched him." },
  { zh: "介子與士卒俱賫金幣，揚言以賜外國為名，至樓蘭。", literal: "Jiezi, together with soldiers, all carried gold and coins, publicly declaring in the name of bestowing gifts on foreign states, and reached Loulan.", idiomatic: "Jiezi went with soldiers carrying gold and coins, publicly declaring he was bestowing gifts on foreign states, and reached Loulan." },
  { zh: "樓蘭王意不親介子，介子陽引去，至其西界，使譯謂曰：「漢使者持黃金、錦繡行賜諸國。", literal: "The king of Loulan was not disposed to be close to Jiezi; Jiezi pretended to leave and reached its western border, sending an interpreter to say: \"The Han envoy holds gold and brocade traveling to bestow on the various states.", idiomatic: "The king of Loulan was not disposed to be friendly toward Jiezi; Jiezi pretended to leave and reached its western border, sending an interpreter to say, \"The Han envoy holds gold and brocade traveling to bestow gifts on the various states." },
  { zh: "王不來受，我去之西國矣。", literal: "If the king does not come to receive them, I am going to the western states.", idiomatic: "If the king does not come to receive them, I am going to the western states." },
  { zh: "」即出金、幣以示譯。", literal: "\" He immediately produced gold and coins to show the interpreter.", idiomatic: "\" He immediately produced gold and coins to show the interpreter." },
  { zh: "譯還報王，王貪漢物，來見使者。", literal: "The interpreter returned and reported to the king; the king, greedy for Han goods, came to see the envoy.", idiomatic: "The interpreter returned and reported to the king; greedy for Han goods, the king came to see the envoy." },
  { zh: "介子與坐飲，陳物示之，飲酒皆醉。", literal: "Jiezi sat and drank with him, displayed the goods to show him, and all became drunk from drinking.", idiomatic: "Jiezi sat drinking with him, displayed the goods, and all became drunk." },
  { zh: "介子謂王曰：「天子使我私報王。", literal: "Jiezi said to the king: \"The Son of Heaven sent me to report privately to the king.", idiomatic: "Jiezi said to the king, \"The Son of Heaven sent me to report privately to the king." },
  { zh: "」王起，隨介子入帳中屏語，壯士二人從後刺之，刃交匈，立死；", literal: "\" The king rose and followed Jiezi into the tent for private speech behind the screen; two stalwarts stabbed him from behind, blades crossing in the chest—he died on the spot;", idiomatic: "\" The king rose and followed Jiezi into the tent for private speech; two stalwarts stabbed him from behind, blades crossing in his chest—he died instantly;" },
  { zh: "其貴人、左右皆散走。", literal: "his nobles and attendants all scattered and fled.", idiomatic: "his nobles and attendants all scattered and fled." },
  { zh: "介子告諭以王負漢罪，「天子遣我誅王，當更立王弟尉屠耆在漢者。", literal: "Jiezi announced and instructed that the king had offended Han: \"The Son of Heaven sent me to execute the king; the king's younger brother Weituqi, who is in Han, ought to be installed instead.", idiomatic: "Jiezi announced that the king had offended Han: \"The Son of Heaven sent me to execute the king; the king's younger brother Weituqi, who is in Han, ought to be installed instead." },
  { zh: "漢兵方至，毋敢動，自令滅國矣！", literal: "Han troops are just arriving—do not dare move, or you will bring destruction on your state yourselves!", idiomatic: "Han troops are just arriving—do not dare move, or you will destroy your state yourselves!" },
  { zh: "」介子遂斬王安歸首，馳傳詣闕，縣首北闕下。", literal: "\" Jiezi thereupon beheaded An Guigui, sped by relay post to the palace, and exposed the head below the Northern Gate.", idiomatic: "\" Jiezi beheaded An Guigui, sped by relay post to the palace, and exposed the head below the Northern Gate." },
  { zh: "乃立尉屠耆為王，更名其國為鄯善，為刻印章；", literal: "He thereupon installed Weituqi as king, renamed the state Shanshan, and had a seal carved;", idiomatic: "He installed Weituqi as king, renamed the state Shanshan, and had a seal carved;" },
  { zh: "賜以宮女為夫人，備車騎、輜重。", literal: "he was bestowed a palace woman as consort and provided chariots, horsemen, and baggage train.", idiomatic: "he was given a palace woman as consort and provided with chariots, horsemen, and baggage train." },
  { zh: "丞相率百官送至橫門外，祖而遣之。", literal: "The Chancellor led the hundred officials to send him off to outside Heng Gate, performed the sending-off libation, and dispatched him.", idiomatic: "The chancellor led the officials to send him off outside Heng Gate, performed the sending-off libation, and dispatched him." },
  { zh: "王自請天子曰：「身在漢久，今歸單弱，而前王有子在，恐為所殺。", literal: "The king himself requested of the Son of Heaven: \"Your servant has long been in Han; now returning, I am alone and weak, while the former king has a son who remains—I fear I will be killed by him.", idiomatic: "The king himself requested of the Son of Heaven, \"I have long been in Han; now returning I am alone and weak, while the former king's son remains—I fear he will kill me." },
  { zh: "國中有伊循城，其地肥美，願漢遣一將屯田積穀，令臣得依其威重。", literal: "Within the state there is Yixun city; its land is fertile and beautiful; your servant wishes Han would dispatch one general to garrison-farm and store grain, so your servant may rely on his authority and weight.", idiomatic: "Within the state is Yixun city, whose land is fertile; I wish Han would dispatch one general to garrison-farm and store grain, so I may rely on his authority." },
  { zh: "」於是漢遣司馬一人、吏士四十人田伊循以填撫之。", literal: "\" Thereupon Han dispatched one major and forty officials and soldiers to farm at Yixun to fill and pacify it.", idiomatic: "\" Thereupon Han dispatched one major and forty officials and soldiers to farm at Yixun to garrison and pacify it." },
  { zh: "秋，七月，乙巳，封范明友為平陵侯，傅介子為義陽侯。", literal: "In autumn, the seventh month, on yisi, Fan Mingyou was enfeoffed as Marquis of Pingling and Fu Jiezi as Marquis of Yiyang.", idiomatic: "In autumn, the seventh month, on yisi, Fan Mingyou was enfeoffed Marquis of Pingling and Fu Jiezi Marquis of Yiyang." },
  { zh: ":臣光曰：王者之於戎狄，叛則討之，服則捨之。", literal: ": Minister Guang said: A king toward the Rong and Di—if they rebel, then chastise them; if they submit, then release them.", idiomatic: ": Minister Guang said: Toward the Rong and Di, if they rebel, chastise them; if they submit, release them." },
  { zh: "今樓蘭王既服其罪，又從而誅之，後有叛者，不可得而懷矣。", literal: "Now the king of Loulan had already submitted to his offense, yet they again followed up and executed him—later when there are rebels, they cannot be won by cherishing them.", idiomatic: "Now the king of Loulan had already submitted for his offense, yet they again executed him—later rebels cannot be won by forbearance." },
  { zh: "必以為有罪而討之，則宜陳師鞠旅，明致其罰。", literal: "If one must think them guilty and chastise them, then one ought to display the army and muster troops, clearly inflicting their punishment.", idiomatic: "If one must deem them guilty and chastise them, one ought to display the army and muster troops, clearly inflicting punishment." },
  { zh: "今乃遣使者誘以金幣而殺之，後有奉使諸國者，復可信乎！", literal: "Now they sent an envoy to lure with gold and coins and kill him—later when there are those who are sent on missions to the various states, can they again be trusted!", idiomatic: "Now they sent an envoy to lure him with gold and coins and kill him—later can envoys sent to the various states still be trusted!" },
  { zh: "且以大漢之強而為盜賊之謀於蠻夷，不亦可羞哉！", literal: "Moreover, for mighty Great Han to use bandit stratagems among the barbarians—is it not also shameful!", idiomatic: "Moreover, for mighty Great Han to use bandit stratagems among the barbarians—is it not shameful!" },
  { zh: "論者或美介子以為奇功，過矣！", literal: "Discussants who sometimes praise Jiezi as having a marvelous achievement go too far!", idiomatic: "Those who praise Jiezi as having a marvelous achievement go too far!" },
  { zh: "1夏，大旱。", literal: "1 In summer, great drought.", idiomatic: "1 In summer, there was a great drought." },
  { zh: "----2秋，罷象郡，分屬鬱林、牂柯。", literal: "----2 In autumn, Xiang commandery was abolished and divided to belong to Yulin and Zangke.", idiomatic: "----2 In autumn, Xiang commandery was abolished and divided between Yulin and Zangke." },
  { zh: "----3冬，十一月，大雷。", literal: "----3 In winter, the eleventh month, great thunder.", idiomatic: "----3 In winter, the eleventh month, there was great thunder." },
  { zh: "----4十二月，庚戌，宜春敬侯王訴薨。", literal: "----4 In the twelfth month, on gengxu, Marquis Jing of Yichun Wang Su died.", idiomatic: "----4 In the twelfth month, on gengxu, Marquis Jing of Yichun Wang Su died." },
  { zh: "1春，正月，募郡國徒築遼東、玄菟城。", literal: "1 In spring, the first month, convicts from commanderies and kingdoms were recruited to build the walls of Liaodong and Xuantu.", idiomatic: "1 In spring, the first month, convicts from commanderies and kingdoms were recruited to build the walls of Liaodong and Xuantu." },
  { zh: "----2夏，赦天下。", literal: "----2 In summer, an amnesty for all under Heaven.", idiomatic: "----2 In summer, an amnesty for all under Heaven." },
  { zh: "----3烏桓復犯塞，遣度遼將軍范明友擊之。", literal: "----3 The Wuhuan again violated the passes; the General Crossing the Liao Fan Mingyou was dispatched to strike them.", idiomatic: "----3 The Wuhuan again violated the passes; General Crossing the Liao Fan Mingyou was dispatched to attack them." },
  { zh: "----4冬，十一月，乙丑，以楊敞為丞相，少府河內蔡義為御史大夫。", literal: "----4 In winter, the eleventh month, on yichou, Yang Chang was made Chancellor and Minister Steward Cai Yi of Henei was made Censor-in-Chief.", idiomatic: "----4 In winter, the eleventh month, on yichou, Yang Chang was made chancellor and Minister Steward Cai Yi of Henei was made censor-in-chief." },
  { zh: "----category:資治通鑑", literal: "----category: Zizhi Tongjian", idiomatic: "----category: Zizhi Tongjian" }
];
